/* JR'SBEAUTYBAR — werkruimte van de eigenares en medewerkers */
{
const A = window.APP, U = window.U, ACT = window.ACT;
const { call, tryCall, esc, eur, dt, dlong, dshort, hm, ico, pill, photo, toast, modal, closeModal, go, cents, eurIn } = A;
const J = A.J;
const DN = ['zo', 'ma', 'di', 'wo', 'do', 'vr', 'za'], DL = ['zondag', 'maandag', 'dinsdag', 'woensdag', 'donderdag', 'vrijdag', 'zaterdag'];

const NAV = [
  ['werk', 'Vandaag', 'vandaag'], ['werk-agenda', 'Agenda', 'agenda'], ['werk-inbox', 'Inbox', 'inbox'], ['werk-klanten', 'Klanten', 'klanten'],
  ['g', 'Salon'], ['werk-bestellingen', 'Bestellingen', 'voorraad'], ['werk-voorraad', 'Voorraad & inkoop', 'voorraad'], ['werk-wachtlijst', 'Wachtlijst', 'agenda'], ['werk-offertes', 'Offertes', 'owner'], ['werk-vip', 'VIP', 'owner'], ['werk-chatbot', 'Chatbot', 'owner'], ['werk-producten', 'Producten', 'owner'], ['werk-diensten', 'Diensten', 'owner'],
  ['g', 'Privé', 'owner'], ['werk-inzichten', 'Inzichten', 'owner'], ['werk-betalingen', 'Betalingen', 'owner'], ['werk-dagafsluiting', 'Dagafsluiting', 'owner'],
  ['g', 'Beheer', 'owner'], ['werk-media', 'Foto’s & video’s', 'owner'], ['werk-berichten', 'Berichten', 'owner'], ['werk-import', 'Salonized-import', 'owner'], ['werk-instellingen', 'Instellingen', 'owner'], ['werk-logboek', 'Logboek', 'owner']];
const allowed = p => U.role === 'owner' || (p !== 'owner' && U.perms.includes(p));

window.renderWork = function (r) {
  if (!U.stok) return login();
  if (!A.E.state.sessions[U.stok]) { U.stok = null; return login('Je sessie is verlopen. Log opnieuw in.'); }
  const inbox = tryCall('stf_inbox'); const unread = inbox.ok ? inbox.ok.filter(c => c.status === 'handoff').length : 0;
  const views = { werk: vToday, 'werk-agenda': vAgenda, 'werk-inbox': vInbox, 'werk-klanten': vClients, 'werk-meer': vMore, 'werk-voorraad': vStock, 'werk-bestellingen': vOrders, 'werk-wachtlijst': vWaitlist, 'werk-offertes': vQuotes, 'werk-vip': vVip, 'werk-chatbot': vBot, 'werk-producten': vProducts, 'werk-diensten': vServices, 'werk-betalingen': vPay, 'werk-inzichten': vInsights, 'werk-dagafsluiting': vClose, 'werk-media': () => window.vMediaView(), 'werk-berichten': vOutbox, 'werk-import': vImport, 'werk-instellingen': vSettings, 'werk-logboek': vAudit };
  let main; try { main = (views[r] || vToday)(); } catch (e) { main = e.code === 'FORBIDDEN' ? noAccess(e.message) : `<div class="note bad">Er ging iets mis: ${esc(e.message)}</div>`; if (!e.code) console.error(e); }
  const cur = r === 'werk-meer' || !['werk', 'werk-agenda', 'werk-inbox'].includes(r) ? 'werk-meer' : r;
  return `<div class="w"><nav class="w-side" aria-label="Werkruimte"><div style="padding:4px 12px 12px"><span class="wordmark script" style="font-size:30px">JR’s beauty bar</span><br><small>Studio · ${U.role === 'owner' ? esc(U.staffName || 'Jada Ramoss') + ' · eigenares' : esc(U.staffName) + ' · medewerker'}</small></div>
    ${NAV.filter(n => allowed(n[2] || 'vandaag')).map(n => n[0] === 'g' ? `<div class="grp">${n[1]}</div>` : `<a href="#${n[0]}" ${r === n[0] ? 'aria-current="page"' : ''}>${esc(n[1])}${n[0] === 'werk-inbox' && unread ? `<span class="badge">${unread}</span>` : ''}</a>`).join('')}
    <div style="margin-top:auto;padding:12px"><button class="btn ghost sm block" data-act="logoutStaff">Uitloggen</button></div></nav>
    <main class="w-main" id="main">${main}</main>
    <nav class="w-bot" aria-label="Werkruimte">${[['werk', 'Vandaag', 'sun'], ['werk-agenda', 'Agenda', 'cal'], ['werk-inbox', 'Inbox', 'inbox'], ['werk-meer', 'Meer', 'more']].map(([k, l, i]) => `<a href="#${k}" ${cur === k ? 'aria-current="page"' : ''}>${ico(i)}<span>${l}</span>${k === 'werk-inbox' && unread ? `<span class="badge">${unread}</span>` : ''}</a>`).join('')}</nav></div>`;
};
const noAccess = m => `<h1>Geen toegang</h1><p class="note bad" style="margin-top:12px">${esc(m || 'Dit onderdeel is alleen voor de eigenares.')} De server heeft het verzoek geweigerd.</p><a class="btn ghost" href="#werk">Naar Vandaag</a>`;
const must = (n, a) => { const r = tryCall(n, a); if (r.err) throw r.err; return r.ok; };
const head = (t, extra = '') => `<div class="w-top"><h1 style="font-size:clamp(28px,4vw,38px)" class="brandish">${esc(t)}</h1><div class="row">${extra}</div></div>`;

function login(msg) {
  const p = U.pin;
  return `<main class="c-main" style="max-width:420px;padding-bottom:40px"><div class="studio-logo"><span class="wordmark script">JR’s beauty bar</span><span>Studio</span></div><h1 class="brandish" style="text-align:center;margin-top:10px">Inloggen</h1><p class="muted" style="text-align:center">Voer je pincode in</p>
  ${msg ? `<p class="note warn">${esc(msg)}</p>` : ''}<div class="dots" aria-label="${p.length} van 4 cijfers">${[0, 1, 2, 3].map(i => `<i class="${i < p.length ? 'f' : ''}"></i>`).join('')}</div>
  <div class="pin">${[1, 2, 3, 4, 5, 6, 7, 8, 9, '', 0, '⌫'].map(k => k === '' ? '<span></span>' : `<button data-act="pinKey" data-k="${k}" aria-label="${k === '⌫' ? 'Wissen' : k}">${k}</button>`).join('')}</div>
  <form data-form="pinSubmit" style="margin-top:16px" class="row"><label class="sr" for="pinIn">Pincode</label><input class="i" id="pinIn" name="pin" inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="Of typ je pincode" style="flex:1"><button class="btn">Inloggen</button></form>
  <p class="muted" style="text-align:center;margin-top:16px">Voorbeeldomgeving: eigenares <b>2468</b>, medewerker <b>1357</b>.</p></main>`;
}
function doLogin(pin) { const r = tryCall('pub_login_staff', { pin }); U.pin = ''; if (r.err) { toast(r.err.message, true); return A.render(); } U.stok = r.ok.token; U.role = r.ok.role; U.staffName = r.ok.name; U.perms = r.ok.perms === 'alles' ? [] : r.ok.perms; A.render(); }
ACT.pinKey = d => { if (d.k === '⌫') U.pin = U.pin.slice(0, -1); else if (U.pin.length < 4) U.pin += d.k; if (U.pin.length === 4) return doLogin(U.pin); A.render(); };
ACT.pinSubmit = f => doLogin((f.pin || '').trim());
ACT.logoutStaff = () => { call('pub_logout', { _t: U.stok }, true); U.stok = null; U.role = null; U.staffName = ''; U.perms = []; U.inboxSel = null; U.clientSel = null; U.sel = {}; toast('Uitgelogd'); go('werk'); };

/* ---------- VANDAAG ---------- */
function vToday() {
  const T = must('stf_today');
  const card = (t, inner, extra = '') => `<section class="card"><div class="head"><h3>${t}</h3>${extra}</div>${inner}</section>`;
  const hr = J.amsParts(Date.now()).hh, groet = hr < 12 ? 'Goedemorgen' : hr < 18 ? 'Goedemiddag' : 'Goedenavond';
  const av = n => `<span class="av" aria-hidden="true">${esc(String(n || '?').replace('Voorbeeldklant ', '').split(' ').map(w => w[0]).join('').slice(0, 2).toUpperCase())}</span>`;
  const nextA = T.appointments.find(a => a.start > Date.now() && a.status === 'confirmed');
  return `<div class="w-hello"><span class="kicker">${esc(dlong(J.amsToUtc(T.date, '12:00')))}</span><h1>${U.role === 'owner' ? 'Welkom ' + esc(U.staffName || 'Jada Ramoss') : groet + ', ' + esc(U.staffName.split(' ')[0])}</h1>${U.role === 'owner' ? `<p class="muted" style="margin:4px 0 0">${groet} — fijn dat je er bent.</p>` : ''}</div>
  <div class="kpis"><div class="k dark"><small>Afspraken vandaag</small><b>${T.appointments.filter(a => a.status !== 'cancelled').length}</b><small>${nextA ? 'Volgende ' + hm(nextA.start) : 'Geen meer vandaag'}</small></div><div class="k"><small>Klaarleggen</small><b>${T.bundles.length}</b></div><div class="k"><small>Te beantwoorden</small><b>${T.unanswered.length}</b></div><div class="k"><small>Inkoopmeldingen</small><b>${T.purchases.length}</b></div>${T.receivable ? `<a class="k" href="#werk-betalingen" style="text-decoration:none"><small>Nog te ontvangen · alleen jij</small><b>${eur(T.receivable.cents)}</b><small>${T.receivable.count} posten${T.receivable.late ? ' · ' + T.receivable.late + ' te laat' : ''}</small></a>` : ''}</div>
  ${dayPlan(T)}
  <div class="cards">
  ${card('Afspraken', T.appointments.length ? `<div class="tl">${T.appointments.map(a => `<button class="it" data-act="apOpen" data-id="${esc(a.id)}"><span class="time">${hm(a.start)}</span><span class="row" style="flex-wrap:nowrap">${av(a.client)}<span><b>${esc(a.client)}</b><br><small>${esc(a.service)}${a.variant ? ' · ' + esc(a.variant) : ''}</small></span></span>${pill(a.status)}</button>`).join('')}</div>` : '<div class="empty">Geen afspraken vandaag.</div>', `<a class="btn quiet sm" href="#werk-agenda">Agenda</a>`)}
  ${card('Klaarleggen', T.bundles.length ? `<div class="list">${T.bundles.map(b => `<div class="li"><span class="time">${b.time}</span><span>${esc(b.variant)}<br><small>${esc(b.client)}</small></span>${b.reserved ? pill('ok', 'Gereserveerd') : pill('bad', 'Niet op voorraad')}</div>`).join('')}</div>` : '<p class="muted">Vandaag hoeft er niets klaargelegd te worden.</p>')}
  ${card('Inkopen', T.purchases.length ? `<div class="list">${T.purchases.map(p => `<div><b>${esc(p.product)} · ${esc(p.label)}</b> ${p.vip ? pill('info', 'VIP') : ''}<br><small class="${p.alert.level === 'tekort' ? '' : 'muted'}">${esc(p.alert.text)}</small></div>`).join('')}</div><a class="btn ghost sm" href="#werk-voorraad" style="margin-top:8px">Naar voorraad</a>` : '<p class="muted">Geen dreigende tekorten.</p>')}
  ${card('Onbeantwoorde vragen', T.unanswered.length ? `<div class="list">${T.unanswered.map(u => `<a class="li" href="#werk-inbox" data-act="inboxOpen" data-id="${esc(u.id)}" style="text-decoration:none;grid-template-columns:1fr auto"><span>${pill('warn', 'Overdracht')}<br><b>${esc(u.client)}</b><br><small>${esc(u.question)}</small></span><span>${ico('chev', 18)}</span></a>`).join('')}</div>` : '<p class="muted">Alles beantwoord.</p>', T.unanswered.length ? `<span class="badge">${T.unanswered.length}</span>` : '')}
  ${T.vipReminders.length ? card('VIP-herinneringen', `<div class="list">${T.vipReminders.map(v => `<div class="li"><span>${pill(v.dueAt < Date.now() ? 'bad' : 'warn', v.dueAt < Date.now() ? 'Nu doen' : 'Binnenkort')}</span><span><b>${esc(v.type)}</b><br><small>${esc(v.client)} · afspraak ${esc(v.date)} · uiterlijk ${esc(dshort(v.dueAt))}</small></span><button class="btn ghost sm" data-act="vipRemDone" data-id="${esc(v.requestId)}" data-t="${esc(v.type)}">Gedaan</button></div>`).join('')}</div>`) : ''}
  ${card('Opvolging', T.tasks.length ? `<div class="list">${T.tasks.map(t => `<div class="li" style="grid-template-columns:1fr auto"><span>${pill(t.kind === 'uitzondering' ? 'bad' : t.kind === 'inkoop' ? 'warn' : 'info', { uitzondering: 'Uitzondering', inkoop: 'Inkoop', intake: 'Intake', vip: 'VIP', nieuw: 'Nieuw' }[t.kind] || 'Taak')}<br>${esc(t.text)}</span><button class="btn ghost sm" data-act="taskDone" data-id="${esc(t.id)}">Afronden</button></div>`).join('')}</div>` : '<p class="muted">Geen openstaande taken.</p>')}
  ${T.repeated.length && U.role === 'owner' ? card('Vragen die vaker terugkomen', T.repeated.map(u => `<p>“${esc(u.question)}” · ${u.count}×</p>`).join('') + '<a class="btn ghost sm" href="#werk-chatbot">Leg één keer uit</a>') : ''}
  </div>`;
}
ACT.taskDone = d => { call('stf_task_done', { id: d.id }); A.render(); };
ACT.vipRemDone = d => { call('stf_vip_reminder_done', { id: d.id, type: d.t }); A.render(); };

function dayPlan(T) {
  const hrs = (A.E.state.settings.hours[J.weekday(T.date)] || [])[0]; if (!hrs) return '<section class="card" style="margin-bottom:14px"><h3>Dagplanning</h3><p class="muted">De salon is vandaag gesloten.</p></section>';
  const a = J.amsToUtc(T.date, hrs[0]), b = J.amsToUtc(T.date, hrs[1]), span = b - a; const pos = x => Math.max(0, Math.min(100, (x - a) / span * 100));
  const now = Date.now(); const H = []; for (let t = a; t <= b; t += 36e5) H.push(t);
  return `<section class="card stack" style="margin-bottom:14px"><div class="head"><h3>Dagplanning</h3><small class="muted">${esc(hrs[0])}–${esc(hrs[1])}</small></div><div class="gantt"><div class="g-axis">${H.map(t => `<span style="left:${pos(t)}%">${hm(t).slice(0, 2)}</span>`).join('')}</div><div class="g-track">${A.E.state.settings.breaks.map(([x, y]) => `<i class="g-break" style="left:${pos(J.amsToUtc(T.date, x))}%;width:${pos(J.amsToUtc(T.date, y)) - pos(J.amsToUtc(T.date, x))}%"></i>`).join('')}${T.appointments.map((x, i) => `<button class="g-blk ${esc(x.status)}" style="left:${pos(x.start)}%;width:${Math.max(4, pos(x.end) - pos(x.start))}%;--d:${i * 90}ms" data-act="apOpen" data-id="${esc(x.id)}" title="${esc(x.client + ' · ' + x.service)}"><b>${esc(hm(x.start))}</b> ${esc(x.client.replace(/^Voorbeeldklant /, ''))}</button>`).join('')}${now > a && now < b ? `<i class="g-now" style="left:${pos(now)}%"></i>` : ''}</div></div>${T.appointments.length ? '' : '<p class="muted">Nog geen afspraken vandaag.</p>'}</section>`;
}

/* ---------- AGENDA ---------- */
function vAgenda() {
  const date = U.agendaDate || A.todayISO(); const view = U.agendaView;
  let from = date, to = date; if (view === 'week') { const wd = (J.weekday(date) + 6) % 7; from = J.addDays(date, -wd); to = J.addDays(from, 6); }
  const G = must('stf_agenda', { from, to });
  const dayList = d => { const s = J.amsToUtc(d, '00:00'), e = J.amsToUtc(J.addDays(d, 1), '00:00'); const items = [...G.appointments.filter(a => a.start >= s && a.start < e).map(a => ({ t: a.start, h: apBtn(a) })), ...G.blocks.filter(b => b.start < e && b.end > s).map(b => ({ t: Math.max(b.start, s), h: `<div class="blk">${esc(hm(Math.max(b.start, s)))}–${esc(hm(Math.min(b.end, e - 60000)))} · ${esc(b.label)} <button class="btn quiet sm" data-act="rmBlock" data-id="${esc(b.id)}">Verwijder</button></div>` })), ...G.vipSpots.filter(v => v.start >= s && v.start < e).map(v => ({ t: v.start, h: `<div class="blk">${esc(hm(v.start))} · VIP-plek ${v.status === 'vip' ? '(tot ' + esc(dshort(v.releaseAt)) + ' ' + esc(hm(v.releaseAt)) + ')' : '— ' + esc(v.status)}</div>` }))].sort((a, b) => a.t - b.t); const hrs = G.hours[J.weekday(d)] || []; return { items, closed: !hrs.length, hrs }; };
  const apBtn = a => `<button class="ap ${esc(a.status)}" data-act="apOpen" data-id="${esc(a.id)}"><span><b class="num">${hm(a.start)}–${hm(a.end)}</b> ${a.vip ? '· VIP' : ''}</span><span><b>${esc(a.client)}</b></span><span>${esc(a.service)}${a.variant ? ' · ' + esc(a.variant) : ''}</span><span>${pill(a.status)}</span></button>`;
  let body;
  if (view === 'week') { const days = []; for (let i = 0; i < 7; i++) days.push(J.addDays(from, i)); body = `<div class="week">${days.map(d => { const L = dayList(d); return `<div class="col"><button class="btn quiet sm" data-act="agDay" data-d="${d}"><b>${DN[J.weekday(d)]} ${+d.slice(8)}</b></button>${L.closed ? '<small class="muted">Gesloten</small>' : ''}${L.items.map(x => x.h).join('')}</div>`; }).join('')}</div>`; }
  else { const L = dayList(date); body = `${L.closed ? '<p class="note">De salon is op deze dag gesloten.</p>' : `<p class="muted">Open ${L.hrs.map(h => h.join('–')).join(', ')} · pauze ${A.E.state.settings.breaks.map(b => b.join('–')).join(', ') || 'geen'}</p>`}<div class="stack">${L.items.map(x => x.h).join('') || '<div class="empty">Geen afspraken.</div>'}</div>`; }
  return head('Agenda', `<button class="btn sm" data-act="newAppt">Nieuwe afspraak</button>`) + `
  <form data-form="cmdPreview" class="card row" style="margin-bottom:14px"><label class="f" style="flex:1 1 260px">Agenda-assistent<input class="i" name="text" placeholder="Blokkeer volgende vrijdag vanaf 14.00 uur" value="${esc(U.sel.cmd || '')}"></label><button class="btn ghost" style="align-self:end">Bekijk vooraf</button></form>
  <div class="row between" style="margin-bottom:12px"><div class="row"><button class="btn ghost sm" data-act="agShift" data-n="-1" aria-label="Vorige">${ico('back', 18)}</button><label class="sr" for="agDate">Datum</label><input class="i" id="agDate" type="date" value="${date}" data-agdate style="width:auto"><button class="btn ghost sm" data-act="agShift" data-n="1" aria-label="Volgende">${ico('chev', 18)}</button><button class="btn quiet sm" data-act="agToday">Vandaag</button></div>
  <div class="chips" role="group" aria-label="Weergave"><button class="chip" data-act="agView" data-v="dag" aria-pressed="${view === 'dag'}">Dag</button><button class="chip" data-act="agView" data-v="week" aria-pressed="${view === 'week'}">Week</button></div></div>
  <h2 style="margin-bottom:10px">${view === 'week' ? `Week van ${esc(dshort(J.amsToUtc(from, '12:00')))}` : esc(dlong(J.amsToUtc(date, '12:00')))}</h2>${body}`;
}
document.addEventListener('change', e => { if (e.target.matches('[data-agdate]') && e.target.value) { U.agendaDate = e.target.value; A.render(); } });
ACT.agShift = d => { U.agendaDate = J.addDays(U.agendaDate || A.todayISO(), (+d.n) * (U.agendaView === 'week' ? 7 : 1)); A.render(); };
ACT.agToday = () => { U.agendaDate = null; A.render(); };
ACT.agView = d => { U.agendaView = d.v; A.render(); };
ACT.agDay = d => { U.agendaDate = d.d; U.agendaView = 'dag'; A.render(); };
ACT.rmBlock = d => { call('stf_remove_block', { id: d.id }); A.render(); };
ACT.cmdPreview = f => {
  U.sel.cmd = f.text; const p = call('stf_parse_command', { text: f.text }); if (!p) return;
  if (p.error) return toast(p.error, true);
  modal('Controleer de wijziging', `<div class="card stack"><p style="font-size:18px"><b>${esc(DL[J.weekday(p.date)])} ${esc(dlong(J.amsToUtc(p.date, '12:00')).replace(/^\w+ /, ''))}</b></p><p>Blok: <b class="num">${esc(p.from)} – ${esc(p.to === '23:59' ? 'einde dag' : p.to)}</b> · ${esc(p.label)}</p>${p.closedDay ? '<p class="note">Let op: de salon is op deze dag al gesloten.</p>' : ''}</div>
  <h3 style="margin:14px 0 6px">Betrokken afspraken (${p.affected.length})</h3>${p.affected.length ? `<p class="muted">Deze afspraken blijven staan. Verplaatsen of annuleren is een aparte keuze.</p><div class="list">${p.affected.map(a => `<div class="li"><span class="time">${hm(a.start)}</span><span>${esc(a.client)}<br><small>${esc(a.service)}</small></span><span class="row"><button class="btn ghost sm" data-act="apMove" data-id="${esc(a.id)}">Verplaatsen</button><button class="btn ghost sm" data-act="apCancel" data-id="${esc(a.id)}">Annuleren</button></span></div>`).join('')}</div>` : '<p class="muted">Geen afspraken in dit blok.</p>'}
  <div class="row end" style="margin-top:16px"><button class="btn ghost" data-act="closeModal">Niet doen</button><button class="btn" data-act="cmdApply" data-start="${p.start}" data-end="${p.end}">Blok toepassen</button></div>`);
};
ACT.cmdApply = d => { const r = call('stf_apply_block', { text: U.sel.cmd, start: +d.start, end: +d.end }); if (!r) return; closeModal(); U.sel.cmd = ''; U.agendaDate = J.amsParts(+d.start).date; U.agendaView = 'dag'; toast('Agenda geblokkeerd' + (r.affected.length ? ` · ${r.affected.length} afspraak(en) vragen je keuze` : '')); A.render(); };
ACT.apOpen = d => {
  const a = A.E.state.appointments.find(x => x.id === d.id); if (!a) return;
  const card = must('stf_client_card', { id: a.clientId }); const ap = card.appointments.find(x => x.id === a.id) || {};
  const post = card.payments && card.payments.find(p => p.id === a.id);
  modal(ap.service || 'Afspraak', `<div class="stack"><p style="font-size:18px"><b>${esc(dt(a.start))}</b> ${pill(a.status)}</p><p><b>${esc(card.client.name)}</b> ${card.client.vip ? pill('info', 'VIP') : ''}<br><small>${esc(card.client.phone)}</small></p>
    ${ap.variant ? `<p>Bundel: <b>${esc(ap.variant)}</b></p>` : ''}${a.note ? `<p class="note">${esc(a.note)}</p>` : ''}
    ${post ? `<div class="sum"><span>Totaal</span><span class="num">${eur(post.total)}</span><span>Betaald</span><span class="num">${eur(post.paid)}</span><span class="t">Open</span><span class="t num">${eur(post.open)} ${pill(post.status)}</span></div>` : ''}
    <div class="row">${['confirmed', 'option', 'hold'].includes(a.status) ? `<button class="btn ghost sm" data-act="apMove" data-id="${esc(a.id)}">Verplaatsen</button><button class="btn ghost sm" data-act="apCancel" data-id="${esc(a.id)}">Annuleren</button>` : ''}<button class="btn ghost sm" data-act="toClient" data-id="${esc(a.clientId)}">Klantkaart</button>${post && post.open && U.role === 'owner' ? `<button class="btn ghost sm" data-act="payOpen" data-id="${esc(a.id)}">Betaling</button>` : ''}</div></div>`);
};
ACT.toClient = d => { closeModal(); U.clientSel = d.id; go('werk-klanten'); };
ACT.apCancel = d => A.confirmBox('Afspraak annuleren?', 'De klant krijgt bericht. Een passende wachtlijstklant krijgt automatisch een tijdelijk aanbod.', 'apDoCancel', { id: d.id }, true);
ACT.apDoCancel = d => { const r = call('stf_cancel', { id: d.id, reason: 'door salon' }); closeModal(); if (r) toast(r.offer ? 'Geannuleerd · aanbod naar ' + r.offer.client : 'Geannuleerd'); A.render(); };
ACT.apMove = d => { const a = A.E.state.appointments.find(x => x.id === d.id); U.sel.mv = { id: a.id, serviceId: a.serviceId, date: J.amsParts(a.start).date }; mvModal(); };
function mvModal() { const M = U.sel.mv; const r = must('stf_slots', { serviceId: M.serviceId, date: M.date, exceptId: M.id });
  modal('Verplaatsen', `<div class="row"><button class="btn ghost sm" data-act="mvDay" data-n="-1" aria-label="Vorige dag">${ico('back', 18)}</button><b>${esc(dlong(J.amsToUtc(M.date, '12:00')))}</b><button class="btn ghost sm" data-act="mvDay" data-n="1" aria-label="Volgende dag">${ico('chev', 18)}</button></div>${r.slots.length ? `<div class="slots" style="margin-top:12px">${r.slots.map(s => `<button class="slot" data-act="mvPick" data-t="${s.start}">${s.time}</button>`).join('')}</div>` : '<div class="empty" style="margin-top:12px">Geen vrije tijden.</div>'}`); }
ACT.mvDay = d => { U.sel.mv.date = J.addDays(U.sel.mv.date, +d.n); mvModal(); };
ACT.mvPick = d => { const r = call('stf_move', { id: U.sel.mv.id, start: +d.t }); if (r) { closeModal(); toast('Verplaatst naar ' + dt(r.appointment.start)); A.render(); } };
ACT.newAppt = () => { const cl = must('stf_clients', {}); const sv = A.E.state.services.filter(s => s.live && !s.extra);
  U.sel.na = { date: U.agendaDate || A.todayISO() };
  modal('Nieuwe afspraak', `<form data-form="naSlots" class="stack"><label class="f">Klant<select class="i" name="clientId">${cl.map(c => `<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select></label><label class="f">Behandeling<select class="i" name="serviceId">${sv.map(s => `<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')}</select></label><label class="f">Bundel (optioneel)<select class="i" name="variantId"><option value="">Geen</option>${A.E.state.products.filter(p => p.category === 'Haarbundels').flatMap(p => p.variants.map(v => `<option value="${esc(v.id)}">${esc(p.name + ' · ' + v.label)}</option>`)).join('')}</select></label><label class="f">Datum<input class="i" type="date" name="date" value="${U.sel.na.date}"></label><button class="btn ghost">Toon vrije tijden</button></form><div id="naOut"></div>`); };
ACT.naSlots = f => { U.sel.na = f; const r = must('stf_slots', { serviceId: f.serviceId, date: f.date }); document.getElementById('naOut').innerHTML = r.slots.length ? `<div class="slots" style="margin-top:12px">${r.slots.map(s => `<button class="slot" data-act="naBook" data-t="${s.start}">${s.time}</button>`).join('')}</div>` : '<div class="empty" style="margin-top:12px">Geen vrije tijden op deze dag.</div>'; };
ACT.naBook = d => { const f = U.sel.na; const r = call('stf_book_for', { clientId: f.clientId, serviceId: f.serviceId, start: +d.t, variantId: f.variantId || null }); if (r) { closeModal(); toast(r.payment ? 'Afspraak vastgehouden; aanbetaling staat open bij de klant' : 'Afspraak vastgelegd'); A.render(); } };

/* ---------- INBOX ---------- */
function vInbox() {
  const L = must('stf_inbox'); const f = U.sel.inboxF || 'handoff';
  const list = L.filter(c => f === 'alle' || c.status === f || (f === 'handoff' && c.status === 'human'));
  const sel = U.inboxSel && L.find(c => c.id === U.inboxSel);
  const C = sel ? must('stf_conversation', { id: sel.id }) : null;
  const card = C ? must('stf_client_card', { id: C.clientId }) : null;
  const chan = { webchat: 'Webchat', instagram: 'Instagram', whatsapp: 'WhatsApp' };
  const listHtml = `<div><div class="chips" style="margin-bottom:10px" role="group" aria-label="Filter">${[['handoff', 'Te beantwoorden'], ['bot', 'Bot'], ['alle', 'Alle']].map(([k, l]) => `<button class="chip" data-act="inboxF" data-f="${k}" aria-pressed="${f === k}">${l}</button>`).join('')}</div>
    <div class="list">${list.map(c => `<button class="li" style="background:${c.id === U.inboxSel ? 'var(--sunk)' : 'none'};border:0;text-align:left;width:100%;cursor:pointer;padding:12px 8px" data-act="inboxOpen" data-id="${esc(c.id)}"><span>${pill(c.status === 'handoff' ? 'warn' : c.status === 'human' ? 'info' : '', c.status === 'handoff' ? 'Overdracht' : c.status === 'human' ? 'Jij' : 'Bot')}</span><span><b>${esc(c.client)}</b> ${c.vip ? '· VIP' : ''}<br><small>${esc(chan[c.channel] || c.channel)} · ${esc(c.last ? c.last.text.slice(0, 60) : '')}</small></span>${c.unread ? `<span class="badge">${c.unread}</span>` : '<span></span>'}</button>`).join('') || '<div class="empty">Geen gesprekken.</div>'}</div>
    <p class="muted" style="margin-top:10px">Webchat is gekoppeld. Instagram en WhatsApp verschijnen hier zodra de officiële koppelingen zijn ingericht.</p></div>`;
  const conv = C ? `<section class="card stack">${U.inboxSel ? `<button class="btn quiet sm hide-d" data-act="inboxBack" style="justify-self:start">${ico('back', 18)} Alle gesprekken</button>` : ''}<div class="head"><h3>${esc(C.client)}</h3>${pill(C.status === 'human' ? 'info' : C.status === 'handoff' ? 'warn' : '', C.status === 'human' ? 'Bot gepauzeerd' : C.status === 'handoff' ? 'Wacht op jou' : 'Bot actief')}</div>
    <div class="msgs" style="max-height:420px;padding:0">${C.messages.map(m => `<div class="msg ${m.from}"><span class="who">${m.from === 'client' ? esc(C.client) : m.from === 'staff' ? esc(m.by || 'Salon') : 'Assistent'} · ${esc(hm(m.at))}</span>${esc(m.text)}</div>`).join('')}</div>
    ${C.handoff ? `<div class="note"><b>Overdracht</b><br><b>Vraag:</b> ${esc(C.handoff.question)}<br><b>Samenvatting:</b> ${esc(C.handoff.summary)}<br><b>Context:</b> ${esc(C.handoff.context.join(' · '))}</div>` : ''}
    <form data-form="inboxReply" class="stack"><label class="f">${C.handoff ? 'Conceptantwoord (pas aan en verstuur)' : 'Bericht'}<textarea class="i" name="text">${esc(C.handoff ? C.handoff.draft : '')}</textarea></label>
    <div class="row">${C.status !== 'human' ? `<button type="button" class="btn ghost sm" data-act="takeOver">Overnemen (bot pauzeren)</button>` : ''}<button class="btn sm">Versturen</button>${C.status !== 'bot' ? `<button type="button" class="btn ghost sm" data-act="releaseBot">Terug naar bot</button>` : ''}${C.handoff && U.role === 'owner' ? `<button type="button" class="btn quiet sm" data-act="saveAsKnowledge">Leer de bot dit antwoord</button>` : ''}</div></form></section>` : '<div class="empty hide-m">Kies een gesprek.</div>';
  const ctx = card ? `<aside class="card ctx stack"><h3>Klantkaart</h3><p><b>${esc(card.client.name)}</b> ${card.client.vip ? pill('info', 'VIP') : ''}<br><small>${esc(card.client.phone)}</small></p><p class="muted">Voorkeur: ${esc([card.client.prefs.color, card.client.prefs.length, card.client.prefs.texture].filter(Boolean).join(' · ') || 'onbekend')}</p>${card.appointments.slice(0, 3).map(a => `<p><small>${esc(dshort(a.start))}</small> ${esc(a.service)} ${pill(a.status)}</p>`).join('')}<button class="btn ghost sm" data-act="toClient" data-id="${esc(card.client.id)}">Open klantkaart</button></aside>` : '<aside class="ctx"></aside>';
  const mobile = window.innerWidth < 1024;
  return head('Inbox') + (mobile ? (C ? conv : listHtml) : `<div class="split inbox">${listHtml}${conv}${ctx}</div>`);
}
ACT.inboxF = d => { U.sel.inboxF = d.f; A.render(); };
ACT.inboxOpen = d => { U.inboxSel = d.id; if (A.route() !== 'werk-inbox') go('werk-inbox'); else A.render(); };
ACT.inboxBack = () => { U.inboxSel = null; A.render(); };
ACT.takeOver = () => { call('stf_take_over', { id: U.inboxSel }); toast('Je hebt het gesprek overgenomen; de bot is gepauzeerd'); A.render(); };
ACT.releaseBot = () => { call('stf_release_bot', { id: U.inboxSel }); toast('De bot beantwoordt weer automatisch'); A.render(); };
ACT.inboxReply = f => { const r = call('stf_reply', { id: U.inboxSel, text: f.text }); if (r) { toast('Verstuurd'); A.render(); } };
ACT.saveAsKnowledge = () => { const c = A.E.state.conversations.find(x => x.id === U.inboxSel); const u = A.E.state.unanswered.find(x => x.question === c.handoff.question); const ta = document.querySelector('[data-form=inboxReply] textarea'); knowledgeEditor({ q: c.handoff.question, keywords: c.handoff.question.toLowerCase().replace(/[^a-z0-9À-ɏ ]/g, '').split(' ').filter(w => w.length > 4).slice(0, 4), answer: ta ? ta.value : '', unansweredId: u && u.id }); };

/* ---------- KLANTEN ---------- */
function vClients() {
  const q = U.sel.cq || ''; const L = must('stf_clients', { q });
  const sel = U.clientSel ? must('stf_client_card', { id: U.clientSel }) : null;
  const list = `<div class="stack"><form data-form="cSearch" class="row"><label class="sr" for="cq">Zoek klant</label><input class="i" id="cq" name="q" value="${esc(q)}" placeholder="Zoek op naam of telefoon" style="flex:1"><button class="btn ghost sm">Zoek</button></form>
    <div class="list">${L.map(c => `<button class="li" style="background:${c.id === U.clientSel ? 'var(--sunk)' : 'none'};border:0;width:100%;text-align:left;cursor:pointer;padding:12px 8px" data-act="cOpen" data-id="${esc(c.id)}"><span>${c.vip ? pill('info', 'VIP') : ''}</span><span><b>${esc(c.name)}</b><br><small>${esc(c.phone)} · ${c.next ? 'volgende ' + esc(dshort(c.next)) : 'geen afspraak'}</small></span>${ico('chev', 18)}</button>`).join('') || '<div class="empty">Geen klanten gevonden.</div>'}</div></div>`;
  const mobile = window.innerWidth < 1024;
  return head('Klanten') + (mobile ? (sel ? clientCard(sel) : list) : `<div class="split">${list}<div class="side-sticky">${sel ? clientCard(sel) : '<div class="empty">Kies een klant.</div>'}</div></div>`);
}
function clientCard(K) {
  const c = K.client;
  return `<section class="stack"><button class="btn quiet sm" data-act="cBack" style="justify-self:start">${ico('back', 18)} Alle klanten</button>
  <div class="card stack"><div class="head"><h2>${esc(c.name)}</h2>${c.vip ? pill('info', 'VIP') : ''}</div>
  <form data-form="cSave" class="stack"><div class="grid2"><label class="f">Naam<input class="i" name="name" value="${esc(c.name)}"></label><label class="f">Telefoon<input class="i" name="phone" value="${esc(c.phone)}"></label><label class="f">E-mail<input class="i" name="email" value="${esc(c.email)}"></label><label class="f">Kanaal<input class="i" value="${esc(c.channel)}" disabled></label></div>
  <div class="grid2"><label class="f">Kleur<input class="i" name="color" value="${esc(c.prefs.color || '')}"></label><label class="f">Lengte<input class="i" name="length" value="${esc(c.prefs.length || '')}"></label><label class="f">Textuur<input class="i" name="texture" value="${esc(c.prefs.texture || '')}"></label></div>
  <label class="f">Notities (alleen salon)<textarea class="i" name="notes">${esc(c.notes || '')}</textarea></label>${U.role === 'owner' ? `<label class="chk"><input type="checkbox" name="vip" ${c.vip ? 'checked' : ''}><span>VIP-klant</span></label>` : ''}<div class="row"><button class="btn sm">Opslaan</button>${U.role === 'owner' ? `<button type="button" class="btn ghost sm" data-act="asClient" data-id="${esc(c.id)}">Bekijk als deze klant</button>` : ''}</div></form></div>
  <details class="d" open><summary>Afspraken (${K.appointments.length})</summary><div class="list">${K.appointments.map(a => `<div class="li"><span>${esc(dshort(a.start))}</span><span>${esc(a.service)}${a.variant ? ' · ' + esc(a.variant) : ''}</span>${pill(a.status)}</div>`).join('') || '<p class="muted">Nog geen afspraken.</p>'}</div></details>
  <details class="d"><summary>Intakes en foto’s (${K.intakes.length})</summary><div class="stack">${K.intakes.map(i => `<div class="card flat stack"><small>${esc(dt(i.createdAt))}</small>${Object.entries(i.answers).filter(([, v]) => v).map(([k, v]) => `<span><b>${esc(k)}:</b> ${esc(v)}</span>`).join('')}${i.photos.length ? `<div class="thumbs">${i.photos.map(p => `<img src="${esc(p.dataUrl.startsWith('data:image/') ? p.dataUrl : '')}" alt="Intakefoto ${esc(p.kind)}" loading="lazy">`).join('')}</div><small>Toestemming: ${i.consent ? 'ja' : 'nee'}</small>` : '<small>Geen foto’s</small>'}
    <div class="row">${i.reviewed ? pill('ok', 'Beoordeeld door ' + i.reviewedBy) : `<button class="btn ghost sm" data-act="intakeOk" data-id="${esc(i.id)}">Markeer beoordeeld</button>`}${U.role === 'owner' ? `<button class="btn ghost sm" data-act="quoteFrom" data-c="${esc(c.id)}" data-i="${esc(i.id)}">Maak offerte</button>` : ''}</div></div>`).join('') || '<p class="muted">Geen intakes.</p>'}${K.intakes.some(i => i.photos.length) ? `<button class="btn danger sm" data-act="staffDelPhotos" data-id="${esc(c.id)}">Verwijder alle foto’s</button>` : ''}</div></details>
  <details class="d"><summary>Bundels en bestellingen</summary><div class="list">${K.bundles.map(b => `<div class="li"><span>Bundel</span><span>${esc(b.label)}</span>${pill(b.status === 'active' ? 'ok' : b.status === 'used' ? 'info' : 'warn', { active: 'Gereserveerd', used: 'Gebruikt', hold: 'Vastgehouden' }[b.status] || b.status)}</div>`).join('')}${K.orders.map(o => `<div class="li"><span class="num">${esc(o.number)}</span><span>${esc(o.items.map(i => i.qty + '× ' + i.name).join(', '))}</span>${pill(o.status)}</div>`).join('') || (!K.bundles.length ? '<p class="muted">Nog niets.</p>' : '')}</div></details>
  <details class="d"><summary>Nazorg en vervolg</summary><div class="list">${K.aftercare.map(m => `<div><small>${esc(dt(m.sendAt))} · ${esc(m.type)} · ${esc(m.status)}</small><p>${esc(m.text)}</p></div>`).join('') || '<p class="muted">Nog niets gepland.</p>'}</div></details>
  ${K.payments ? `<details class="d"><summary>Betalingen ${pill('info', 'Alleen jij')}</summary><div class="list">${K.payments.map(p => `<div class="li"><span>${pill(p.status)}</span><span>${esc(p.label)}</span><b class="num">${eur(p.open)} open</b></div>`).join('') || '<p class="muted">Geen posten.</p>'}</div></details>` : ''}
  ${K.conversations.map(v => `<button class="btn ghost sm" data-act="inboxOpen" data-id="${esc(v.id)}">Open gesprek (${esc(v.channel)})</button>`).join(' ')}</section>`;
}
ACT.cSearch = f => { U.sel.cq = f.q; A.render(); };
ACT.cOpen = d => { U.clientSel = d.id; A.render(); };
ACT.cBack = () => { U.clientSel = null; A.render(); };
ACT.cSave = f => { const a = { id: U.clientSel, name: f.name, phone: f.phone, email: f.email, notes: f.notes, prefs: { color: f.color, length: f.length, texture: f.texture } }; if (U.role === 'owner') a.vip = !!f.vip; if (call('stf_client_update', a)) toast('Klantkaart opgeslagen'); A.render(); };
ACT.intakeOk = d => { call('stf_intake_review', { id: d.id }); A.render(); };
ACT.staffDelPhotos = d => A.confirmBox('Foto’s verwijderen?', 'Alle intakefoto’s van deze klant worden definitief verwijderd.', 'doStaffDel', { id: d.id }, true);
ACT.doStaffDel = d => { closeModal(); const r = call('stf_delete_photos', { clientId: d.id }); if (r) toast(r.deleted + ' foto’s verwijderd'); A.render(); };
ACT.asClient = d => { const r = call('own_client_link', { id: d.id }); if (!r) return; const s = tryCall('pub_client_link', { link: r.link }); if (s.ok) { A.lsSet('jrs_ctok', s.ok.token); location.href = 'index.html#home'; } };

/* ---------- MEER ---------- */
function vMore() { return head('Meer') + `<div class="more">${NAV.filter(n => n[0] !== 'g' && !['werk', 'werk-agenda', 'werk-inbox'].includes(n[0]) && allowed(n[2])).map(n => `<a href="#${n[0]}">${esc(n[1])}${ico('chev', 18)}</a>`).join('')}</div><div style="margin-top:16px"><button class="btn ghost" data-act="logoutStaff">Uitloggen</button></div>`; }

/* ---------- VOORRAAD ---------- */
function vStock() {
  const F = must('stf_forecast', { weeks: U.sel.wk || 6 });
  return head('Voorraad & inkoop', `<label class="f" style="flex-direction:row">Periode <select class="i" data-wk style="width:auto">${[2, 4, 6, 8, 12, 26].map(w => `<option value="${w}" ${(U.sel.wk || 6) === w ? 'selected' : ''}>${w} weken</option>`).join('')}</select></label>`) +
  `<p class="muted">Berekend uit bevestigde afspraken, opties, reserveringen en ingestelde levertijden — ook VIP-afspraken.</p><div class="scroll"><table class="tbl stackt"><thead><tr><th>Product</th><th>Variant</th><th class="num">Voorraad</th><th class="num">Gereserveerd</th><th class="num">Na reservering</th><th>Levertijd</th><th>Melding</th><th></th></tr></thead><tbody>
  ${F.map(f => `<tr><td data-l="Product">${esc(f.product)}</td><td data-l="Variant">${esc(f.label)}</td><td data-l="Voorraad" class="num">${f.stock}</td><td data-l="Gereserveerd" class="num">${f.reserved}${f.vip ? ' · VIP' : ''}</td><td data-l="Na reservering" class="num">${f.after}</td><td data-l="Levertijd">${f.leadDays} dagen</td><td data-l="Melding">${f.alert ? pill(f.alert.level === 'tekort' ? 'bad' : 'warn', f.alert.level === 'tekort' ? 'Tekort' : 'Laag') + '<br><small>' + esc(f.alert.text) + '</small>' : pill('ok', 'In orde')}</td><td><button class="btn ghost sm" data-act="stockEdit" data-id="${esc(f.variantId)}" data-s="${f.stock}" data-l="${esc(f.product + ' · ' + f.label)}">Aanpassen</button></td></tr>`).join('')}</tbody></table></div>`;
}
document.addEventListener('change', e => { if (e.target.matches('[data-wk]')) { U.sel.wk = +e.target.value; A.render(); } });
ACT.stockEdit = d => modal('Voorraad aanpassen', `<form data-form="stockSave" class="stack"><p><b>${esc(d.l)}</b></p><input type="hidden" name="id" value="${esc(d.id)}"><label class="f">Aantal op voorraad<input class="i" type="number" min="0" name="stock" value="${esc(d.s)}" inputmode="numeric"></label><label class="chk"><input type="checkbox" name="purchased"><span>Inkoop ontvangen (rond openstaande inkooptaken af)</span></label><button class="btn">Opslaan</button></form>`);
ACT.stockSave = f => { if (call('stf_stock_update', { variantId: f.id, stock: f.stock, purchased: !!f.purchased })) { closeModal(); toast('Voorraad bijgewerkt'); A.render(); } };

/* ---------- BESTELLINGEN ---------- */
function vOrders() {
  const O = must('stf_orders'); const f = U.sel.of || 'open';
  const flt = { open: o => ['betaald', 'klaar'].includes(o.status), verzonden: o => o.status === 'verzonden', klaar: o => ['afgehaald', 'geleverd'].includes(o.status), alle: () => true };
  const L = O.filter(flt[f]);
  return head('Bestellingen') + `<div class="chips" style="margin-bottom:12px">${[['open', 'Te verwerken'], ['verzonden', 'Onderweg'], ['klaar', 'Afgerond'], ['alle', 'Alle']].map(([k, l]) => `<button class="chip" data-act="ofF" data-f="${k}" aria-pressed="${f === k}">${l} · ${O.filter(flt[k]).length}</button>`).join('')}</div>
  <div class="stack">${L.map(o => `<article class="card stack"><div class="head"><b>${esc(o.number)} · ${esc(o.client || '')}</b>${pill(o.status === 'betaald' ? 'warn' : o.status === 'hold' ? '' : 'ok', o.status === 'hold' ? 'Wacht op betaling' : o.status)}</div>
    <ul class="r-lines">${o.items.map(i => `<li><span>${i.qty}× ${esc(i.name)}</span><span class="num">${eur(i.qty * i.priceCents)}</span></li>`).join('')}<li><span>${o.delivery.type === 'bezorgen' ? 'Bezorgen: ' + esc(o.delivery.country) + ' · ' + esc(o.delivery.address || '') : 'Afhalen in de salon'}</span><span class="num">${eur(o.delivery.rateCents || 0)}</span></li></ul>
    <div class="row between"><b class="num">${eur(o.totalCents)}</b><span class="row">${o.status === 'betaald' ? (o.delivery.type === 'bezorgen' ? `<button class="btn sm" data-act="ordShip" data-id="${esc(o.id)}">Verzonden</button>` : `<button class="btn sm" data-act="ordSt" data-id="${esc(o.id)}" data-s="klaar">Klaar om af te halen</button>`) : ''}${o.status === 'klaar' ? `<button class="btn sm" data-act="ordSt" data-id="${esc(o.id)}" data-s="afgehaald">Afgehaald</button>` : ''}${o.status === 'verzonden' ? `<button class="btn sm" data-act="ordSt" data-id="${esc(o.id)}" data-s="geleverd">Geleverd</button>` : ''}</span></div></article>`).join('') || '<div class="empty">Geen bestellingen in deze lijst.</div>'}</div>`;
}
ACT.ofF = d => { U.sel.of = d.f; A.render(); };
ACT.ordSt = d => { if (call('stf_order_status', { id: d.id, status: d.s })) toast('Status bijgewerkt; de klant krijgt bericht'); A.render(); };
ACT.ordShip = d => modal('Verzonden', `<form data-form="ordShipSave" class="stack"><input type="hidden" name="id" value="${esc(d.id)}"><label class="f">Track &amp; trace (optioneel)<input class="i" name="track"></label><button class="btn">Markeer als verzonden</button></form>`);
ACT.ordShipSave = f => { if (call('stf_order_status', { id: f.id, status: 'verzonden', track: f.track })) { closeModal(); toast('Verzonden; de klant krijgt bericht'); A.render(); } };

/* ---------- WACHTLIJST ---------- */
function vWaitlist() {
  const W = must('stf_waitlist');
  return head('Wachtlijst') + `<p class="muted">Bij annulering krijgt één passende klant een tijdelijk aanbod (${A.E.state.settings.waitlistOfferMinutes} min). ${A.E.state.settings.vipPriority ? 'VIP-klanten gaan voor.' : 'Volgorde op aanmelding.'}</p>
  <div class="list">${W.map((w, i) => `<div class="li"><span class="num">${i + 1}</span><span><b>${esc(w.client)}</b> ${w.vip ? pill('info', 'VIP') : ''}<br><small>${esc(w.service)} · ${esc(w.days.map(d => DN[d]).join(', ') || 'alle dagen')} · ${esc(w.parts.join(', ') || 'hele dag')}</small></span>${pill(w.status === 'aanbod' ? 'warn' : w.status === 'geboekt' ? 'ok' : '', w.status)}</div>`).join('') || '<div class="empty">Niemand op de wachtlijst.</div>'}</div>`;
}

/* ---------- OFFERTES ---------- */
function vQuotes() {
  const Q = must('own_quotes');
  return head('Offertes', `<button class="btn sm" data-act="quoteFrom">Nieuwe offerte</button>`) + `<div class="list">${Q.slice().reverse().map(q => `<div class="li"><span class="num">${esc(q.number)}</span><span><b>${esc(q.client)}</b> · ${eur(q.totalCents)}<br><small>Akkoord ${q.steps.akkoord ? '✓' : '—'} · Aanbetaling ${q.steps.aanbetaling ? '✓' : '—'} · Tijdslot ${q.steps.tijdslot ? '✓' : '—'} · geldig tot ${esc(dshort(q.validUntil))}</small></span><span class="row">${pill(q.status)}<button class="btn ghost sm" data-act="quoteLink" data-t="${esc(q.token)}">Klantlink</button></span></div>`).join('') || '<div class="empty">Nog geen offertes. Maak er een vanuit een intake of hier.</div>'}</div>`;
}
ACT.quoteLink = d => { modal('Persoonlijke offertelink', `<p>In de live versie stuur je de klant een unieke link. In deze voorbeeldomgeving open je de offerte zoals de klant hem ziet.</p><div class="row end" style="margin-top:12px"><button class="btn" data-act="quoteAsClient" data-t="${esc(d.t)}">Open als klant</button></div>`); };
ACT.quoteAsClient = d => { closeModal(); A.lsSet('jrs_open_quote', d.t); location.href = 'index.html#offerte'; };
ACT.quoteFrom = d => {
  const cl = must('stf_clients', {}); const sv = A.E.state.services.filter(s => s.live); const vr = d.vip ? A.E.state.vipRequests.find(x => x.id === d.vip) : null;
  const svcId = vr ? vr.serviceId : 'svc_sewin'; const s0 = sv.find(s => s.id === svcId) || sv[0];
  U.sel.qf = { clientId: d.c || (vr && vr.clientId) || (cl[0] && cl[0].id), intakeId: d.i || null, vipRequestId: vr ? vr.id : null, date: vr ? vr.date : A.todayISO() };
  modal(vr ? 'Offerte voor VIP-aanvraag' : 'Nieuwe offerte', `<form data-form="quoteSave" class="stack"><label class="f">Klant<select class="i" name="clientId">${cl.map(c => `<option value="${esc(c.id)}" ${c.id === U.sel.qf.clientId ? 'selected' : ''}>${esc(c.name)}</option>`).join('')}</select></label>
  <fieldset style="border:0;padding:0;margin:0" class="stack"><legend style="font-weight:700">Regels</legend>${[[s0.name, s0.priceCents], ['Haar', 0], ['', 0]].map(([l, c], i) => `<div class="grid2"><label class="f">Omschrijving<input class="i" name="l${i}" value="${esc(l)}"></label><label class="f">Bedrag (€)<input class="i" name="c${i}" inputmode="decimal" value="${c ? eurIn(c) : ''}"></label></div>`).join('')}</fieldset>
  <div class="grid2"><label class="f">Aanbetaling (€)<input class="i" name="deposit" inputmode="decimal" value="${eurIn(s0.depositCents)}"></label><label class="f">Geldig (dagen)<input class="i" name="validDays" type="number" min="1" value="7"></label></div>
  <label class="f">Voorwaarden<textarea class="i" name="terms">De aanbetaling wordt verrekend met het totaal. Annuleren of verplaatsen kan tot 48 uur vooraf. (Voorlopige tekst)</textarea></label>
  <fieldset style="border:0;padding:0;margin:0" class="stack"><legend style="font-weight:700">Tijdslot in optie (optioneel)</legend><div class="grid2"><label class="f">Behandeling<select class="i" name="serviceId">${sv.map(s => `<option value="${esc(s.id)}" ${s.id === svcId ? 'selected' : ''}>${esc(s.name)}</option>`).join('')}</select></label><label class="f">Datum<input class="i" type="date" name="date" value="${esc(U.sel.qf.date)}"></label><label class="f">Tijd<input class="i" type="time" name="time" step="1800" value="10:00"></label><label class="f">Bundel<select class="i" name="variantId"><option value="">Geen</option>${A.E.state.products.filter(p => p.category === 'Haarbundels').flatMap(p => p.variants.map(v => `<option value="${esc(v.id)}">${esc(p.name + ' · ' + v.label)}</option>`)).join('')}</select></label></div><label class="chk"><input type="checkbox" name="withSlot" checked><span>Zet dit tijdslot in optie tot de offerte verloopt</span></label></fieldset>
  <button class="btn">Offerte maken en klaarzetten</button></form>`);
};
ACT.quoteSave = f => { const lines = [0, 1, 2].map(i => ({ label: f['l' + i], cents: cents(f['c' + i]) })).filter(l => l.label && l.cents > 0);
  const a = { clientId: f.clientId, intakeId: U.sel.qf.intakeId, vipRequestId: U.sel.qf.vipRequestId, lines, depositCents: cents(f.deposit), validDays: +f.validDays || 7, terms: f.terms };
  if (f.withSlot && f.date && f.time) { a.serviceId = f.serviceId; a.start = J.amsToUtc(f.date, f.time); a.variantId = f.variantId || null; }
  const r = call('own_quote_create', a); if (r) { closeModal(); toast('Offerte ' + r.number + ' klaargezet'); go('werk-offertes'); } };

/* ---------- VIP ---------- */
function vVip() {
  const V = must('own_vip');
  return head('VIP', `<button class="btn sm" data-act="vipSpotNew">VIP-plek openzetten</button>`) + `<p class="muted">VIP-plekken zijn ${V.windowHours} uur alleen voor VIP-klanten (${V.clients.length}) en gaan daarna naar de gewone agenda. VIP-voorrang bij annuleringen: ${V.priority ? 'aan' : 'uit'}. <a href="#werk-instellingen">Wijzigen</a></p>
  <h2 style="margin:16px 0 8px">Aanvragen</h2><div class="list">${V.requests.slice().reverse().map(v => `<div class="li"><span>${pill(v.status)}</span><span><b>${esc(v.client)}</b> · ${esc(v.service)}<br><small>${esc(v.date)} · ${esc(v.occasion || '—')}${v.optionExpires && v.status === 'Optie' ? ' · optie tot ' + esc(dshort(v.optionExpires)) : ''}</small>${(v.reminders || []).length ? `<br><small>${v.reminders.map(r => `${esc(r.type)}: ${esc(dshort(r.dueAt))}${r.done ? ' ✓' : ''}`).join(' · ')}</small>` : ''}</span><span class="row">${v.status === 'Aangevraagd' ? `<button class="btn ghost sm" data-act="quoteFrom" data-vip="${esc(v.id)}">Optie + offerte</button>` : ''}${['Aangevraagd', 'Optie'].includes(v.status) ? `<button class="btn quiet sm" data-act="vipExpire" data-id="${esc(v.id)}">Laat vervallen</button>` : ''}</span></div>`).join('') || '<div class="empty">Nog geen VIP-aanvragen.</div>'}</div>
  <h2 style="margin:16px 0 8px">VIP-plekken</h2><div class="list">${V.spots.slice().reverse().map(s => `<div class="li"><span>${pill(s.status === 'vip' ? 'info' : s.status === 'taken' ? 'ok' : '', s.status === 'vip' ? 'Alleen VIP' : s.status === 'taken' ? 'Geboekt' : 'Vrij voor iedereen')}</span><span>${esc(dt(s.start))}<br><small>VIP tot ${esc(dt(s.releaseAt))}</small></span><span></span></div>`).join('') || '<p class="muted">Nog geen VIP-plekken.</p>'}</div>`;
}
ACT.vipExpire = d => { call('own_vip_status', { id: d.id, status: 'Vervallen' }); A.render(); };
ACT.vipSpotNew = () => modal('VIP-plek openzetten', `<form data-form="vipSpotSave" class="stack"><div class="grid2"><label class="f">Datum<input class="i" type="date" name="date" min="${A.todayISO()}" required></label><label class="f">Starttijd<input class="i" type="time" name="time" step="1800" value="10:00" required></label></div><p class="muted">De plek is ${A.E.state.settings.vipWindowHours} uur alleen zichtbaar voor VIP-klanten.</p><button class="btn">Openzetten</button></form>`);
ACT.vipSpotSave = f => { if (!f.date) return toast('Kies een datum', true); if (call('own_vip_spot', { start: J.amsToUtc(f.date, f.time) })) { closeModal(); toast('VIP-plek staat open'); A.render(); } };

/* ---------- CHATBOT ---------- */
function vBot() {
  const K = must('own_knowledge'); const tab = U.sel.botTab || (K.training.status === 'klaar' ? 'kennis' : 'training');
  const tabs = [['training', 'Training'], ['voorstellen', 'Voorstellen'], ['kennis', 'Kennis'], ['regels', 'Regels'], ['vragen', 'Onbeantwoord'], ['test', 'Testgesprek']];
  let body = '';
  if (tab === 'training') {
    const T = K.training, idx = U.train != null ? U.train : Math.min(T.idx, K.questions.length - 1), q = K.questions[idx], done = T.idx >= K.questions.length;
    body = T.status === 'gepauzeerd' ? `<div class="card stack"><p>De training is gepauzeerd bij vraag ${T.idx + 1} van ${K.questions.length}.</p><button class="btn" data-act="trainPause" data-p="0">Doorgaan</button></div>` :
      `<div class="card stack"><div class="row between"><span class="muted">Vraag ${idx + 1} van ${K.questions.length} · ongeveer 10 minuten</span><button class="btn quiet sm" data-act="trainPause" data-p="1">Pauzeren</button></div><div class="prog" aria-hidden="true"><i style="width:${Math.round(Math.min(T.idx, K.questions.length) / K.questions.length * 100)}%"></i></div>
      ${done && U.train == null ? `<p class="note ok">Training afgerond. Bekijk de voorstellen en publiceer wat klopt.</p><div class="row"><button class="btn" data-act="botTab" data-t="voorstellen">Naar voorstellen</button><button class="btn ghost" data-act="trainGo" data-i="0">Antwoorden nalopen</button></div>` :
      `<p class="muted">Ik speel een klant. Antwoord zoals je het een klant zou vertellen.</p><div class="bubble-bot">${esc(q.q)}</div>
      <form data-form="trainAnswer" class="stack"><input type="hidden" name="idx" value="${idx}"><label class="f">Jouw antwoord<textarea class="i" name="text" rows="4">${esc((T.answers[q.key] || {}).text || '')}</textarea></label><small class="muted">Liever inspreken? Gebruik de microfoonknop van je toetsenbord.</small>
      <div class="row"><button class="btn">Opslaan & volgende</button><button type="button" class="btn ghost" data-act="trainSkip" data-i="${idx}">Overslaan</button>${idx > 0 ? `<button type="button" class="btn quiet" data-act="trainGo" data-i="${idx - 1}">Vorige</button>` : ''}</div></form>`}</div>`;
  } else if (tab === 'voorstellen') {
    const S = must('own_training_suggestions');
    body = S.length ? `<p class="muted">Niets gaat live zonder jouw goedkeuring. Pas aan waar nodig en publiceer per antwoord of regel.</p><div class="stack">${S.map((s, i) => s.kind === 'antwoord' ? `<form class="card stack" data-form="sugPublish"><input type="hidden" name="i" value="${i}"><div class="head"><b>${esc(s.q)}</b>${pill('concept', 'Voorgesteld klantantwoord')}</div><label class="f">Antwoord<textarea class="i" name="answer">${esc(s.answer)}</textarea></label><label class="f">Herkenwoorden (komma’s)<input class="i" name="keywords" value="${esc(s.keywords.join(', '))}"></label><div class="row"><button class="btn sm" name="pub" value="1">Publiceren</button></div></form>`
      : s.kind === 'regel' ? `<div class="card stack"><div class="head"><b>${esc(s.text)}</b>${pill('concept', 'Voorgestelde boekingsregel')}</div><small class="muted">Op basis van: “${esc(s.basedOn)}”</small><button class="btn sm" data-act="rulePublish" data-k="${esc(s.key)}" data-t="${esc(s.text)}" style="justify-self:start">Regel publiceren</button></div>`
      : `<form class="card stack" data-form="tonePublish"><div class="head"><b>Aanspreekstijl</b>${pill('concept', 'Voorstel')}</div><label class="f">Begroeting<textarea class="i" name="greeting">${esc(s.text)}</textarea></label><label class="f">Afsluiting na een boeking<input class="i" name="closing" value="${esc(K.tone.closing || '')}"></label><button class="btn sm" style="justify-self:start">Stijl publiceren</button></form>`).join('')}</div>` : '<div class="empty">Nog geen voorstellen. Doorloop eerst de training.</div>';
  } else if (tab === 'kennis') {
    body = `<div class="row" style="margin-bottom:10px"><button class="btn sm" data-act="knNew">Nieuw antwoord</button></div><div class="stack">${K.knowledge.map(k => `<div class="card stack"><div class="head"><b>${esc(k.q)}</b>${pill(k.status)}</div><p>${esc(k.answer)}</p><small class="muted">Herkenwoorden: ${esc(k.keywords.join(', '))}${k.approvedBy ? ` · goedgekeurd door ${esc(k.approvedBy)} op ${esc(dt(k.approvedAt))}` : ''}${k.history.length ? ` · ${k.history.length} eerdere versie(s)` : ''}</small><div class="row"><button class="btn ghost sm" data-act="knEdit" data-id="${esc(k.id)}">Aanpassen</button>${k.status === 'published' ? `<button class="btn quiet sm" data-act="knRetract" data-id="${esc(k.id)}">Intrekken</button>` : ''}</div></div>`).join('')}</div>
    <p class="muted" style="margin-top:12px">Algemene salonkennis staat los van privécontext per klant. Klantgesprekken worden nooit automatisch algemene kennis.</p>`;
  } else if (tab === 'regels') {
    body = `<div class="stack">${K.rules.map(r => `<div class="card row between"><span><b>${esc(r.text)}</b><br><small class="muted">${r.approvedBy ? 'Goedgekeurd: ' + esc(r.approvedBy) + ' · ' + esc(dt(r.approvedAt)) : ''}</small></span><span class="row">${pill(r.status === 'published' && r.enabled ? 'published' : r.status === 'published' ? '' : r.status, r.status === 'published' && !r.enabled ? 'Uitgeschakeld' : null)}<button class="btn ghost sm" data-act="ruleToggle" data-id="${esc(r.id)}" data-t="${esc(r.text)}" data-e="${r.enabled ? 0 : 1}">${r.enabled ? 'Uitschakelen' : 'Inschakelen'}</button></span></div>`).join('')}</div><p class="muted" style="margin-top:10px">Regels zijn configureerbare voorstellen. Ze gelden pas na jouw controle.</p>`;
  } else if (tab === 'vragen') {
    body = K.unanswered.filter(u => !u.resolved).length ? `<div class="list">${K.unanswered.filter(u => !u.resolved).sort((a, b) => b.count - a.count).map(u => `<div class="li"><span>${pill(u.count > 1 ? 'warn' : '', u.count + '×')}</span><span>“${esc(u.question)}”${u.count > 1 && !u.asked ? '<br><small><b>De bot vraagt één keer:</b> deze vraag komt vaker terug — wil je het uitleggen?</small>' : ''}</span><button class="btn ghost sm" data-act="knFromQ" data-id="${esc(u.id)}">Uitleggen</button></div>`).join('')}</div>` : '<div class="empty">Geen open vragen.</div>';
  } else if (tab === 'test') {
    body = `<form data-form="botTest" class="card stack"><p class="muted">Start een nieuw testgesprek en controleer welk antwoord klanten nu krijgen.</p><label class="f">Vraag<input class="i" name="q" value="${esc(U.sel.botQ || '')}" placeholder="Bijv. Hoe verzorg ik mijn extensions daarna?"></label><button class="btn sm" style="justify-self:start">Vraag stellen in nieuw gesprek</button>${U.sel.botA ? `<div class="msg bot" style="max-width:100%"><span class="who">Assistent</span>${esc(U.sel.botA)}</div>` : ''}</form>`;
  }
  return head('Chatbot') + `<div class="chips" style="margin-bottom:14px" role="tablist">${tabs.map(([k, l]) => `<button class="chip" role="tab" data-act="botTab" data-t="${k}" aria-pressed="${tab === k}">${l}${k === 'vragen' && K.unanswered.filter(u => !u.resolved).length ? ' · ' + K.unanswered.filter(u => !u.resolved).length : ''}</button>`).join('')}</div>${body}`;
}
ACT.botTab = d => { U.sel.botTab = d.t; U.train = null; A.render(); };
ACT.trainAnswer = f => { call('own_training_answer', { idx: +f.idx, text: f.text }); U.train = null; A.render(); };
ACT.trainSkip = d => { call('own_training_answer', { idx: +d.i, skip: true }); U.train = null; A.render(); };
ACT.trainGo = d => { U.train = +d.i; A.render(); };
ACT.trainPause = d => { call('own_training_pause', { paused: d.p === '1' }); A.render(); };
ACT.sugPublish = f => { const s = must('own_training_suggestions')[+f.i]; const ex = A.E.state.knowledge.find(k => k.q === s.q); if (call('own_knowledge_save', { id: ex && ex.id, q: s.q, keywords: f.keywords.split(',').map(x => x.trim()), answer: f.answer, publish: true })) toast('Live voor klanten'); A.render(); };
ACT.rulePublish = d => { if (call('own_rule_save', { key: d.k, text: d.t, publish: true })) toast('Regel gepubliceerd'); A.render(); };
ACT.ruleToggle = d => { call('own_rule_save', { id: d.id, text: d.t, enabled: d.e === '1', publish: true }); A.render(); };
ACT.tonePublish = f => { if (call('own_tone_publish', f)) toast('Aanspreekstijl gepubliceerd'); A.render(); };
function knowledgeEditor(k) { U.sel.kn = k; modal(k.id ? 'Antwoord aanpassen' : 'Nieuw antwoord', `<form data-form="knSave" class="stack"><label class="f">Vraag of onderwerp<input class="i" name="q" value="${esc(k.q || '')}" required></label><label class="f">Antwoord voor klanten<textarea class="i" name="answer" rows="5">${esc(k.answer || '')}</textarea></label><label class="f">Herkenwoorden (komma’s)<input class="i" name="keywords" value="${esc((k.keywords || []).join(', '))}"></label><div class="row end"><button class="btn ghost" name="mode" value="concept">Opslaan als concept</button><button class="btn" name="mode" value="pub">Publiceren</button></div></form>`); }
ACT.knNew = () => knowledgeEditor({});
ACT.knEdit = d => knowledgeEditor(A.E.state.knowledge.find(k => k.id === d.id));
ACT.knRetract = d => { call('own_knowledge_retract', { id: d.id }); toast('Ingetrokken: de bot gebruikt dit niet meer'); A.render(); };
ACT.knFromQ = d => { const u = A.E.state.unanswered.find(x => x.id === d.id); call('own_unanswered_ask', { id: u.id }, true); knowledgeEditor({ q: u.question, keywords: u.key.split(' ').filter(Boolean), unansweredId: u.id }); };
ACT.knSave = (f) => { const pub = f.mode === 'pub'; const k = U.sel.kn || {}; if (call('own_knowledge_save', { id: k.id, q: f.q, answer: f.answer, keywords: f.keywords.split(',').map(x => x.trim()), publish: pub, unansweredId: k.unansweredId })) { closeModal(); toast(pub ? 'Live voor klanten' : 'Opgeslagen als concept'); A.render(); } };
ACT.botTest = f => { U.sel.botQ = f.q; const c = tryCall('pub_client_start', { name: 'Testgesprek eigenares', phone: '0690' + String(Date.now()).slice(-6) }); if (c.err) return toast(c.err.message, true); const r = A.E.api('cli_chat', { text: f.q }, c.ok.token); U.sel.botA = r.text + (r.handoff ? '  → (doorgezet naar inbox)' : ''); A.render(); };

/* ---------- PRODUCTEN & DIENSTEN ---------- */
function vProducts() {
  const P = must('own_products');
  return head('Producten', `<button class="btn sm" data-act="prodEdit">Nieuw product</button>`) + `<div class="stack">${P.map(p => `<div class="card row between"><span><b>${esc(p.name)}</b> · ${esc(p.category)}<br><small class="muted">${p.variants.length} varianten · ${p.variants.reduce((a, v) => a + v.stock, 0)} op voorraad</small></span><span class="row">${pill(p.live ? 'published' : 'concept')}<button class="btn ghost sm" data-act="prodEdit" data-id="${esc(p.id)}">Bewerken</button></span></div>`).join('')}</div><p class="muted" style="margin-top:10px">Is er een bestaande webshop? Die kan gekoppeld worden zodra er een officiële koppeling beschikbaar is; tot die tijd is dit de ingebouwde shop.</p>`;
}
ACT.prodEdit = d => { const p = d.id ? A.E.state.products.find(x => x.id === d.id) : { name: '', category: 'Haarbundels', description: '', variants: [{ label: '', priceCents: 0, stock: 0, leadDays: 10, reorderPoint: 2 }], live: false };
  U.sel.pv = p.variants.length;
  modal(d.id ? 'Product bewerken' : 'Nieuw product', `<form data-form="prodSave" class="stack"><input type="hidden" name="id" value="${esc(p.id || '')}"><div class="grid2"><label class="f">Naam<input class="i" name="name" value="${esc(p.name)}" required></label><label class="f">Categorie<input class="i" name="category" value="${esc(p.category)}" list="cats"></label></div><datalist id="cats"><option>Haarbundels</option><option>Accessoires</option><option>Verzorging</option><option>Supplementen</option></datalist>
  <label class="f">Omschrijving<textarea class="i" name="description">${esc(p.description)}</textarea></label><label class="chk"><input type="checkbox" name="supplement" ${p.supplement ? 'checked' : ''}><span>Supplement (bot toont alleen goedgekeurde info en verwijst gezondheidsvragen door)</span></label><label class="f">Goedgekeurde productinformatie<textarea class="i" name="approvedInfo">${esc(p.approvedInfo || '')}</textarea></label>
  <h3>Varianten</h3>${p.variants.map((v, i) => `<div class="card flat stack"><input type="hidden" name="vid${i}" value="${esc(v.id || '')}"><div class="grid2"><label class="f">Label<input class="i" name="vl${i}" value="${esc(v.label)}"></label><label class="f">Prijs (€)<input class="i" name="vp${i}" inputmode="decimal" value="${eurIn(v.priceCents)}"></label><label class="f">Voorraad<input class="i" type="number" min="0" name="vs${i}" value="${v.stock}"></label><label class="f">Levertijd (dagen)<input class="i" type="number" min="0" name="vd${i}" value="${v.leadDays}"></label></div></div>`).join('')}
  <label class="chk"><input type="checkbox" name="live" ${p.live ? 'checked' : ''}><span>Live in de shop (anders concept)</span></label><button class="btn">Opslaan</button></form>`); };
ACT.prodSave = f => { const vs = []; for (let i = 0; i < U.sel.pv; i++) if (f['vl' + i]) vs.push({ id: f['vid' + i] || null, label: f['vl' + i], priceCents: cents(f['vp' + i]), stock: +f['vs' + i], leadDays: +f['vd' + i], reorderPoint: 2 }); if (call('own_product_save', { id: f.id || null, name: f.name, category: f.category, description: f.description, supplement: !!f.supplement, approvedInfo: f.approvedInfo, live: !!f.live, variants: vs })) { closeModal(); toast(f.live ? 'Live in de shop' : 'Opgeslagen als concept'); A.render(); } };
function vServices() {
  const S = must('own_services');
  return head('Diensten', `<button class="btn sm" data-act="svcEdit">Nieuwe dienst</button>`) + `<p class="note warn">De Salonized-dienstenpagina gaf tijdens onderzoek een 403-fout. Alle diensten hieronder zijn voorbeelddata of onbevestigd. Alleen bevestigde diensten worden boekbaar in de live versie.</p>
  <div class="scroll" style="margin-top:12px"><table class="tbl stackt"><thead><tr><th>Dienst</th><th class="num">Prijs</th><th class="num">Duur</th><th>Intake</th><th class="num">Aanbetaling</th><th>Verificatie</th><th>Bron · controle</th><th></th></tr></thead><tbody>${S.map(s => `<tr><td data-l="Dienst"><b>${esc(s.name)}</b><br>${pill(s.live ? 'published' : 'concept', s.live ? 'Boekbaar' : 'Niet boekbaar')}</td><td data-l="Prijs" class="num">${eur(s.priceCents)}</td><td data-l="Duur" class="num">${s.durationMin}+${s.prepMin}+${s.bufferMin} min</td><td data-l="Intake">${s.intakeRequired ? 'Ja' : 'Nee'}</td><td data-l="Aanbetaling" class="num">${eur(s.depositCents)}</td><td data-l="Verificatie">${pill(s.verify.status)}</td><td data-l="Bron"><small>${esc(s.verify.source)} · ${esc(s.verify.checkedAt)}</small></td><td><button class="btn ghost sm" data-act="svcEdit" data-id="${esc(s.id)}">Bewerken</button></td></tr>`).join('')}</tbody></table></div>`;
}
ACT.svcEdit = d => { const s = d.id ? A.E.state.services.find(x => x.id === d.id) : { name: '', category: 'extensions', priceCents: 0, durationMin: 60, prepMin: 15, bufferMin: 15, depositCents: 0, followUpWeeks: 0, care: '', verify: { status: 'onbevestigd' } };
  modal(d.id ? 'Dienst bewerken' : 'Nieuwe dienst', `<form data-form="svcSave" class="stack"><input type="hidden" name="id" value="${esc(s.id || '')}"><div class="grid2"><label class="f">Naam<input class="i" name="name" value="${esc(s.name)}" required></label><label class="f">Categorie<select class="i" name="category">${['intake', 'extensions', 'styling'].map(c => `<option ${c === s.category ? 'selected' : ''}>${c}</option>`).join('')}</select></label><label class="f">Prijs (€)<input class="i" name="price" inputmode="decimal" value="${eurIn(s.priceCents)}"></label><label class="f">Aanbetaling (€)<input class="i" name="deposit" inputmode="decimal" value="${eurIn(s.depositCents)}"></label><label class="f">Duur (min)<input class="i" type="number" name="dur" value="${s.durationMin}"></label><label class="f">Voorbereiding (min)<input class="i" type="number" name="prep" value="${s.prepMin}"></label><label class="f">Buffer (min)<input class="i" type="number" name="buf" value="${s.bufferMin}"></label><label class="f">Vervolgvoorstel na (weken)<input class="i" type="number" name="fu" value="${s.followUpWeeks}"></label></div>
  <label class="chk"><input type="checkbox" name="intake" ${s.intakeRequired ? 'checked' : ''}><span>Intake vereist voor nieuwe klanten</span></label><label class="chk"><input type="checkbox" name="variant" ${s.needsVariant ? 'checked' : ''}><span>Klant kiest een bundel</span></label><label class="f">Onderhoudsinstructies na afloop<textarea class="i" name="care">${esc(s.care)}</textarea></label>
  <p>Verificatie: ${pill(s.verify.status)}</p><label class="chk"><input type="checkbox" name="confirm"><span>Ik bevestig naam, prijs, duur en voorwaarden van deze dienst</span></label><label class="chk"><input type="checkbox" name="live" ${s.live ? 'checked' : ''}><span>Boekbaar voor klanten (alleen na bevestiging)</span></label><button class="btn">Opslaan</button></form>`); };
ACT.svcSave = f => { if (call('own_service_save', { id: f.id || null, name: f.name, category: f.category, priceCents: cents(f.price), depositCents: cents(f.deposit), durationMin: +f.dur, prepMin: +f.prep, bufferMin: +f.buf, followUpWeeks: +f.fu, care: f.care, intakeRequired: !!f.intake, needsVariant: !!f.variant, confirm: !!f.confirm, live: !!f.live })) { closeModal(); toast('Dienst opgeslagen'); A.render(); } };

/* ---------- BETALINGEN (alleen eigenares) ---------- */
function vPay() {
  const F = must('own_finance'); const flt = U.payFilter; const q = (U.sel.pq || '').toLowerCase();
  const fmap = { open: p => ['Nog te ontvangen', 'Te laat', 'Uitzondering'].includes(p.status), late: p => p.status === 'Te laat', gepland: p => p.status === 'Gepland', betaald: p => p.status === 'Betaald', alle: () => true };
  let rows = F.posts.filter(fmap[flt]).filter(p => !q || (p.client || '').toLowerCase().includes(q) || p.label.toLowerCase().includes(q));
  const sk = U.paySort; rows.sort((a, b) => sk === 'open' ? b.open - a.open : sk === 'client' ? (a.client || '').localeCompare(b.client || '') : a.due - b.due);
  const exc = F.payments.filter(p => p.exception && p.status === 'paid' && !F.payments.some(r => r.refundOf === p.id));
  const wide = window.innerWidth >= 768;
  return head('Betalingen', pill('info', 'Alleen zichtbaar voor jou')) + `<div class="cards" style="margin-bottom:14px"><div class="card"><small>Nog te ontvangen</small><div class="kpi">${eur(F.totals.receivable)}</div></div><div class="card"><small>Te laat</small><div class="kpi">${eur(F.totals.late)}</div></div><div class="card"><small>Gepland (bij afspraak)</small><div class="kpi">${eur(F.totals.planned)}</div></div></div>
  ${exc.length ? `<div class="note bad" style="margin-bottom:12px"><b>${exc.length} late betaling(en) na verlopen reservering.</b> Kies per geval een nieuw tijdstip of betaal terug. ${exc.map(p => `<br>${esc(p.client)} · ${eur(p.amountCents)} <button class="btn sm" data-act="refund" data-id="${esc(p.id)}">Terugbetalen</button>`).join('')}</div>` : ''}
  <div class="row between" style="margin-bottom:10px"><div class="chips" role="group" aria-label="Filter">${[['open', 'Open'], ['late', 'Te laat'], ['gepland', 'Gepland'], ['betaald', 'Betaald'], ['alle', 'Alle']].map(([k, l]) => `<button class="chip" data-act="payF" data-f="${k}" aria-pressed="${flt === k}">${l}</button>`).join('')}</div><form data-form="paySearch" class="row"><label class="sr" for="pq">Zoek</label><input class="i" id="pq" name="q" value="${esc(U.sel.pq || '')}" placeholder="Zoek klant" style="width:180px"><button class="btn ghost sm">Zoek</button></form></div>
  ${rows.length ? (wide ? `<div class="scroll"><table class="tbl"><thead><tr><th><button data-act="paySort" data-k="client">Klant</button></th><th>Afspraak of bestelling</th><th class="num">Totaal</th><th class="num">Aanbetaling</th><th class="num">Betaald</th><th class="num">Retour</th><th class="num"><button data-act="paySort" data-k="open">Open</button></th><th><button data-act="paySort" data-k="due">Vervalt</button></th><th>Status</th></tr></thead><tbody>${rows.map(p => `<tr style="cursor:pointer" data-act="payOpen" data-id="${esc(p.id)}"><td>${esc(p.client)}</td><td>${esc(p.label)}</td><td class="num">${eur(p.total)}</td><td class="num">${eur(p.deposit)}</td><td class="num">${eur(p.paid)}</td><td class="num">${eur(p.refunds)}</td><td class="num"><b>${eur(p.open)}</b></td><td>${esc(dshort(p.due))}</td><td>${pill(p.status)}</td></tr>`).join('')}</tbody></table></div>`
    : `<div class="list">${rows.map(p => `<details class="d" style="border:0;border-bottom:1px solid var(--line);border-radius:0;background:none"><summary><span><b>${esc(p.client)}</b><br><small>${esc(p.label)}</small></span><span style="text-align:right"><b class="num">${eur(p.open)}</b><br>${pill(p.status)}</span></summary><div><div class="sum"><span>Totaal</span><span class="num">${eur(p.total)}</span><span>Aanbetaling</span><span class="num">${eur(p.deposit)}</span><span>Betaald</span><span class="num">${eur(p.paid)}</span><span>Retouren</span><span class="num">${eur(p.refunds)}</span><span>Vervaldatum</span><span>${esc(dshort(p.due))}</span></div><button class="btn ghost sm" data-act="payOpen" data-id="${esc(p.id)}" style="margin-top:8px">Acties</button></div></details>`).join('')}</div>`) : '<div class="empty">Geen posten in deze selectie.</div>'}`;
}
ACT.payF = d => { U.payFilter = d.f; A.render(); };
ACT.paySort = d => { U.paySort = d.k; A.render(); };
ACT.paySearch = f => { U.sel.pq = f.q; A.render(); };
ACT.payOpen = d => {
  const F = must('own_finance'); const p = F.posts.find(x => x.id === d.id); const pays = F.payments.filter(x => x.refId === d.id);
  modal(p.label, `<p><b>${esc(p.client)}</b> ${pill(p.status)}</p><div class="sum" style="margin:10px 0"><span>Totaal</span><span class="num">${eur(p.total)}</span><span>Betaald</span><span class="num">${eur(p.paid)}</span><span>Retouren</span><span class="num">${eur(p.refunds)}</span><span class="t">Open</span><span class="t num">${eur(p.open)}</span></div>
  ${p.open ? `<form data-form="payRegister" class="card stack"><h3>Betaling registreren</h3><input type="hidden" name="refId" value="${esc(p.id)}"><div class="grid2"><label class="f">Methode<select class="i" name="method"><option value="pin">Pin</option><option value="overboeking">Overboeking</option><option value="contant">Contant</option></select></label><label class="f">Bedrag (€)<input class="i" name="amount" inputmode="decimal" value="${eurIn(p.open)}"></label></div><button class="btn sm">Registreren</button></form>
  <form data-form="payLinkPrep" class="card stack" style="margin-top:10px"><h3>Betaallink of herinnering</h3><input type="hidden" name="refId" value="${esc(p.id)}"><p class="muted">Het bedrag wordt bij verzenden opnieuw berekend (nu ${eur(p.open)}).</p><fieldset style="border:0;padding:0;margin:0" class="stack"><label class="chk"><input type="radio" name="when" value="concept" checked><span>Klaarzetten, ik verstuur zelf</span></label><label class="chk"><input type="radio" name="when" value="nu"><span>Nu versturen</span></label><label class="chk"><input type="radio" name="when" value="later"><span>Inplannen op</span></label><input class="i" type="datetime-local" name="at"></fieldset><button class="btn ghost sm">Bevestigen</button></form>` : ''}
  <h3 style="margin:14px 0 6px">Historie</h3><div class="list">${pays.map(x => `<div class="li"><span>${pill(x.status)}</span><span>${esc(x.kind)} · ${esc(x.method)} · ${eur(x.amountCents)}<br><small>${(x.log || []).map(l => esc(dt(l.at) + ' ' + l.by + ': ' + l.what)).join('<br>')}</small></span>${x.status === 'paid' && x.kind !== 'terugbetaling' ? `<button class="btn ghost sm" data-act="refund" data-id="${esc(x.id)}">Terugbetalen</button>` : '<span></span>'}</div>`).join('') || '<p class="muted">Nog geen betalingen.</p>'}</div>
  ${A.E.state.paylinks.filter(l => l.refId === p.id).map(l => `<p class="muted">Betaallink: ${esc(l.status)}${l.status === 'concept' ? ` <button class="btn sm" data-act="plSend" data-id="${esc(l.id)}">Nu versturen</button>` : ''}</p>`).join('')}`);
};
ACT.payRegister = f => { if (call('own_register_payment', { refId: f.refId, method: f.method, amountCents: cents(f.amount) })) { toast('Betaling geregistreerd'); ACT.payOpen({ id: f.refId }); A.render(); } };
ACT.payLinkPrep = f => { const a = { refId: f.refId, when: f.when }; if (f.when === 'later') { if (!f.at) return toast('Kies een moment', true); const [dd, tt] = f.at.split('T'); a.sendAt = J.amsToUtc(dd, tt); } if (call('own_paylink', a)) { toast(f.when === 'nu' ? 'Betaallink klaargezet voor de klant' : f.when === 'later' ? 'Ingepland' : 'Klaargezet als concept'); ACT.payOpen({ id: f.refId }); } };
ACT.plSend = d => { const pl = call('own_paylink_send', { id: d.id }); if (pl) { toast(pl.status === 'klaargezet' ? 'Verstuurd met actueel bedrag ' + eur(pl.amountCents) : pl.status); ACT.payOpen({ id: pl.refId }); } };
ACT.refund = d => A.confirmBox('Terugbetalen?', 'Online betalingen worden bijgewerkt zodra de provider de terugbetaling bevestigt. Handmatige betalingen worden direct verwerkt.', 'doRefund', { id: d.id }, true);
ACT.doRefund = d => { closeModal(); const r = call('own_refund', { id: d.id }); if (r) { toast('Terugbetaling ' + (r.refund.status === 'refunded' ? 'verwerkt' : 'aangevraagd')); if (r.refund.providerRef) A.tryCall('pub_test_checkout', { providerRef: r.refund.providerRef, status: 'refunded' }); } A.render(); };

/* ---------- INZICHTEN (alleen eigenares) ---------- */
function vInsights() {
  const I = must('own_insights'); const D = ['zo', 'ma', 'di', 'wo', 'do', 'vr', 'za'];
  const maxW = Math.max(1, ...I.weeks.map(w => w.cents)); const days = [2, 3, 4, 5, 6].filter(d => (I.hours[d] || []).length); const hrs = []; for (let h = 9; h <= 19; h++) hrs.push(h);
  const maxH = Math.max(1, ...Object.values(I.heat)); const maxT = Math.max(1, ...I.top.map(t => t.n));
  const occ = Math.round(I.occupancy * 100), C2 = 2 * Math.PI * 42; const tot = I.newC + I.retC || 1;
  return head('Inzichten', pill('info', 'Alleen zichtbaar voor jou')) + `${I.demo ? '<p class="note" style="margin-bottom:14px">Gebaseerd op voorbeeldhistorie van 8 weken. Met echte afspraken vullen deze grafieken zich vanzelf.</p>' : ''}
  <div class="kpis"><div class="k dark"><small>Omzet deze maand</small><b>${eur(I.monthCents)}</b><small>${I.monthN} afspraken</small></div><div class="k"><small>Komende 7 dagen</small><b>${I.nextWeek}</b><small>afspraken</small></div>
  <div class="k ring-k"><svg viewBox="0 0 100 100" class="ring-svg" aria-hidden="true"><circle cx="50" cy="50" r="42"/><circle cx="50" cy="50" r="42" class="v" style="stroke-dasharray:${C2};stroke-dashoffset:${C2 * (1 - I.occupancy)}"/></svg><span><small>Bezetting 7 dagen</small><b>${occ}%</b></span></div><div class="k"><small>Gemiddelde besteding</small><b>${eur(I.avg)}</b></div></div>
  <div class="ins-grid"><section class="card stack"><div class="head"><h3>Omzet per week</h3><small class="muted">laatste 8 weken</small></div><div class="bars" role="img" aria-label="Omzet per week">${I.weeks.map((w, i) => `<div class="bar-c"><span class="bar-v num">${w.cents ? eur(w.cents).replace(',00', '') : ''}</span><div class="ibar" style="--h:${Math.round(w.cents / maxW * 100)}%;--d:${i * 60}ms" title="${esc(eur(w.cents))} · ${w.n} afspraken"></div><small>${esc(dshort(w.from).replace(/^\w+ /, ''))}</small></div>`).join('')}</div></section>
  <section class="card stack"><div class="head"><h3>Drukste momenten</h3><small class="muted">starttijden per dag en uur</small></div><div class="heat" style="grid-template-columns:34px repeat(${hrs.length},minmax(0,1fr))"><span></span>${hrs.map(h => `<small>${h}</small>`).join('')}${days.map(d => `<small class="hd">${D[d]}</small>${hrs.map(h => { const v = I.heat[d + '-' + h] || 0; return `<i style="--o:${(v / maxH).toFixed(2)}" title="${D[d]} ${h}:00 · ${v}"></i>`; }).join('')}`).join('')}</div></section>
  <section class="card stack"><div class="head"><h3>Populairste diensten</h3></div>${I.top.map((t, i) => `<div class="hb"><span>${esc(t.name)}</span><div class="hb-t"><i style="--w:${Math.round(t.n / maxT * 100)}%;--d:${i * 80}ms"></i></div><b class="num">${t.n}×</b></div>`).join('') || '<p class="muted">Nog geen afspraken.</p>'}</section>
  <section class="card stack"><div class="head"><h3>Klanten afgelopen 30 dagen</h3></div><div class="donut-w"><svg viewBox="0 0 100 100" class="donut" aria-hidden="true"><circle cx="50" cy="50" r="38"/><circle cx="50" cy="50" r="38" class="v" style="stroke-dasharray:${2 * Math.PI * 38};stroke-dashoffset:${2 * Math.PI * 38 * (1 - I.retC / tot)}"/></svg><div class="stack" style="gap:6px"><span>${pill('ok', 'Terugkerend')} <b>${I.retC}</b></span><span>${pill('warn', 'Nieuw')} <b>${I.newC}</b></span></div></div></section></div>`;
}

/* ---------- DAGAFSLUITING ---------- */
function vClose() {
  const date = U.sel.closeDate || A.todayISO(); const D = must('own_day_close', { date }); const lab = { online: 'Online', pin: 'Pin', overboeking: 'Overboeking', contant: 'Contant' };
  return head('Dagafsluiting', `<label class="sr" for="cd">Datum</label><input class="i" id="cd" type="date" value="${date}" data-closedate style="width:auto">`) + `<p class="muted">${esc(dlong(J.amsToUtc(date, '12:00')))} · ${D.appointments} afspraken · alleen zichtbaar voor jou</p>
  <div class="cards" style="margin-top:12px"><div class="card"><small>Ontvangen</small><div class="kpi">${eur(D.receivedTotal)}</div><div class="sum" style="margin-top:8px">${Object.entries(D.received).map(([k, v]) => `<span>${esc(lab[k] || k)}</span><span class="num">${eur(v)}</span>`).join('') || '<span class="muted">Nog niets ontvangen</span>'}</div></div><div class="card"><small>Terugbetalingen</small><div class="kpi">${eur(D.refunds)}</div></div><div class="card"><small>Openstaand</small><div class="kpi">${eur(D.open.reduce((a, p) => a + p.open, 0))}</div><small>${D.open.length} posten · gepland later ${eur(D.planned)}</small></div></div>
  <h2 style="margin:18px 0 8px">Vraagt aandacht</h2><div class="list">${D.open.map(p => `<div class="li"><span>${pill(p.status)}</span><span>${esc(p.client)} · ${esc(p.label)}</span><button class="btn ghost sm" data-act="payOpen" data-id="${esc(p.id)}">${eur(p.open)}</button></div>`).join('')}${D.attention.map(t => `<div class="li"><span>${pill(t.kind === 'uitzondering' ? 'bad' : 'warn', t.kind)}</span><span>${esc(t.text)}</span><span></span></div>`).join('')}${!D.open.length && !D.attention.length ? '<p class="muted">Niets openstaand. Mooie dag!</p>' : ''}</div>`;
}
document.addEventListener('change', e => { if (e.target.matches('[data-closedate]')) { U.sel.closeDate = e.target.value; A.render(); } });

/* ---------- MEDIA ---------- */
function vMedia() {
  const M = must('own_media'); const sv = A.E.state.services;
  return head('Foto’s & portfolio') + `<form data-form="mediaAdd" class="card stack"><h3>Foto toevoegen</h3><label class="f">Bestand<input class="i" type="file" accept="image/*" data-mediafile></label>${U.sel.mediaUrl ? `<div class="thumbs"><img src="${esc(U.sel.mediaUrl)}" alt="Voorbeeld"></div>` : ''}
    <div class="grid2"><label class="f">Soort<select class="i" name="kind"><option value="portfolio">Portfolio (look)</option><option value="hero">Hoofdfoto klantscherm</option><option value="product">Productfoto</option></select></label><label class="f">Onderwerp of look<input class="i" name="subject" list="looks" required></label><datalist id="looks"><option>Sew-in</option><option>Pre colored</option><option>Curls</option><option>Ponytails</option><option>HU/HD</option><option>Bundels</option></datalist>
    <label class="f">Herkomst<input class="i" name="source" placeholder="Eigen foto, cliënt cam, fotograaf…" required></label><label class="f">Gekoppelde dienst<select class="i" name="serviceId"><option value="">Onbekend → adviesaanvraag</option>${sv.map(s => `<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')}</select></label><label class="f">Gekoppeld product<select class="i" name="productId"><option value="">Geen</option>${A.E.state.products.map(p => `<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></label></div>
    <label class="chk"><input type="checkbox" name="consent"><span>Er is toestemming voor publicatie (bij herkenbare klanten: schriftelijk)</span></label><label class="chk"><input type="checkbox" name="publish" checked><span>Direct tonen in de klantomgeving</span></label><button class="btn sm" style="justify-self:start">Toevoegen</button></form>
  <h2 style="margin:18px 0 8px">Bibliotheek (${M.length})</h2>${M.length ? `<div class="stack">${M.map(m => `<div class="card stack"><div class="row between"><b>${esc(m.subject)}</b><span class="row">${pill(m.publish ? 'published' : 'concept', m.publish ? 'Zichtbaar' : 'Verborgen')}</span></div><small class="muted">${esc(m.kind)} · ${esc(m.source)} · toestemming vastgelegd · ${m.serviceId ? 'dienst gekoppeld' : 'adviesaanvraag'}</small>
    <div class="grid2"><div><small>Telefoon (4:5)</small>${photo(m)}</div><div><small>Laptop (16:10)</small>${photo(m, 'wide')}</div></div>
    <form data-form="mediaFocus" class="row"><input type="hidden" name="id" value="${esc(m.id)}"><label class="f">Focus horizontaal<input type="range" min="0" max="100" name="x" value="${parseInt(m.focus) || 50}"></label><label class="f">Focus verticaal<input type="range" min="0" max="100" name="y" value="${parseInt((m.focus || '').split(' ')[1]) || 40}"></label><button class="btn ghost sm">Focuspunt opslaan</button><button type="button" class="btn ghost sm" data-act="mediaToggle" data-id="${esc(m.id)}" data-p="${m.publish ? 0 : 1}">${m.publish ? 'Verbergen' : 'Tonen'}</button><button type="button" class="btn danger sm" data-act="mediaRm" data-id="${esc(m.id)}">Verwijderen</button></form></div>`).join('')}</div>` : '<div class="empty">Nog geen foto’s. De klantomgeving toont tot die tijd een rustige, gemarkeerde fotoplek.</div>'}
  <p class="muted" style="margin-top:12px">Video: start via een herkenbare afspeelknop met posterbeeld; muziek alleen met bevestigde rechten. Voor-en-na alleen bij dezelfde behandeling en met toestemming.</p>`;
}
document.addEventListener('change', async e => { if (!e.target.matches('[data-mediafile]')) return; try { U.sel.mediaUrl = await A.readImage(e.target.files[0], 1600); A.render(); } catch (er) { toast(er.message, true); } });
ACT.mediaAdd = f => { if (!U.sel.mediaUrl) return toast('Kies eerst een foto', true); if (call('own_media_add', { ...f, consent: !!f.consent, publish: !!f.publish, dataUrl: U.sel.mediaUrl })) { U.sel.mediaUrl = null; toast('Foto toegevoegd'); A.render(); } };
ACT.mediaFocus = f => { call('own_media_update', { id: f.id, focus: `${f.x}% ${f.y}%` }); A.render(); };
ACT.mediaToggle = d => { call('own_media_update', { id: d.id, publish: d.p === '1' }); A.render(); };
ACT.mediaRm = d => { call('own_media_update', { id: d.id, remove: true }); A.render(); };

/* ---------- BERICHTEN, IMPORT, INSTELLINGEN, LOGBOEK ---------- */
function vOutbox() {
  const O = must('own_outbox');
  return head('Berichten') + `<p class="note">Bevestigingen, reminders, nazorg en vervolgvoorstellen worden hier klaargezet. Versturen via WhatsApp, sms of e-mail volgt zodra een officiële berichtendienst is gekoppeld, met aparte instellingen voor bevestigingen, reminders en marketing.</p>
  <div class="list" style="margin-top:12px">${O.map(m => `<div class="li"><span>${pill(m.status === 'gepland' ? 'info' : 'warn', m.status)}</span><span><b>${esc(m.client || '')}</b> · ${esc(m.type)}<br><small>${esc(dt(m.sendAt))}</small><br>${esc(m.text)}</span><span></span></div>`).join('') || '<div class="empty">Nog geen berichten.</div>'}</div>`;
}
function vImport() {
  const R = U.sel.imp;
  return head('Salonized-import') + `<div class="card stack"><p>Exporteer klanten uit Salonized als CSV en plak ze hier. Je ziet eerst een voorbeeld; er wordt niets overgezet tot je bevestigt.</p><p class="muted">Officiële synchronisatie wordt pas aangeboden als er een werkende koppeling is. Tot dan is per fase één agenda leidend (nu: <b>${A.E.state.settings.leadingAgenda === 'app' ? 'deze app' : 'Salonized'}</b>, wijzigen bij Instellingen).</p>
  <form data-form="impPreview" class="stack"><label class="f">CSV (naam;telefoon;email;afspraak;aanbetaling)<textarea class="i" name="csv" rows="6">${esc(U.sel.csv || '')}</textarea></label><div class="row"><button class="btn sm">Voorbeeld maken</button><button type="button" class="btn ghost sm" data-act="impSample">Voorbeeldbestand invullen</button></div></form></div>
  ${R ? `<div class="card stack" style="margin-top:12px"><h3>Importvoorbeeld</h3><div class="sum"><span>Regels</span><b class="num">${R.total}</b><span>Nieuwe klanten</span><b class="num">${R.new.length}</b><span>Dubbele klanten</span><span class="num">${R.duplicates.length}</span><span>Ontbrekende velden</span><span class="num">${R.missing.length}</span><span>Oude afspraken (alleen historie)</span><span class="num">${R.oldAppointments}</span><span>Toekomstige afspraken</span><span class="num">${R.futureAppointments}</span><span>Met aanbetaling</span><span class="num">${R.deposits}</span><span>Mogelijke conflicten</span><span class="num">${R.conflicts.length}</span></div>
  ${R.duplicates.length ? `<p class="muted">Dubbel: ${esc(R.duplicates.map(x => x.name).join(', '))}</p>` : ''}${R.missing.length ? `<p class="muted">Ontbreekt: ${esc(R.missing.map(m => m.row + ' (' + m.missing.join(', ') + ')').join('; '))}</p>` : ''}${R.conflicts.length ? `<p class="note warn">Conflict: ${esc(R.conflicts.map(c => c.name + ' ' + c.when).join(', '))}</p>` : ''}
  ${R.done ? `<p class="note ok">${R.done.imported} klanten geïmporteerd. Handmatig over te zetten: ${R.done.manual.appointments} toekomstige afspraken, ${R.done.manual.deposits} aanbetalingen, ${R.done.manual.conflicts} conflicten.</p>` : `<button class="btn sm" data-act="impApply" style="justify-self:start">Import bevestigen</button>`}</div>` : ''}`;
}
ACT.impSample = () => { const d = J.addDays(A.todayISO(), 10); U.sel.csv = `naam;telefoon;email;afspraak;aanbetaling\nSara de Vries;0612345678;sara@example.nl;2026-03-02 10:00;0\nVoorbeeldklant Naomi;0600000002;;${d} 11:00;50\nLeila Bakker;;leila@example.nl;;\nMila Jansen;0687654321;;${d} 14:00;25`; A.render(); };
ACT.impPreview = f => { U.sel.csv = f.csv; const r = call('own_import_preview', { csv: f.csv }); if (r) { U.sel.imp = r; A.render(); } };
ACT.impApply = () => { const r = call('own_import_apply', { id: U.sel.imp.id }); if (r) { U.sel.imp.done = r; toast(r.imported + ' klanten geïmporteerd'); A.render(); } };
function vSettings() {
  const S = must('own_settings');
  return head('Instellingen') + `<form data-form="setSave" class="stack lg"><section class="card stack"><h3>Openingstijden</h3>${[2, 3, 4, 5, 6, 0, 1].map(d => { const h = (S.hours[d] || [])[0]; return `<div class="row"><b style="width:90px">${DL[d]}</b><label class="chk"><input type="checkbox" name="open${d}" ${h ? 'checked' : ''}>open</label><label class="sr" for="f${d}">Van</label><input class="i" id="f${d}" type="time" name="from${d}" value="${h ? h[0] : '09:30'}" style="width:auto"><span>–</span><label class="sr" for="t${d}">Tot</label><input class="i" id="t${d}" type="time" name="to${d}" value="${h ? h[1] : '18:00'}" style="width:auto"></div>`; }).join('')}
    <div class="grid2"><label class="f">Pauze van<input class="i" type="time" name="bf" value="${(S.breaks[0] || [])[0] || ''}"></label><label class="f">Pauze tot<input class="i" type="time" name="bt" value="${(S.breaks[0] || [])[1] || ''}"></label><label class="f">Lange behandelingen (min) mogen door de pauze heen<input class="i" type="number" name="ltb" value="${S.longThroughBreakMin || 0}"></label><label class="f">Verlof van<input class="i" type="date" name="lf"></label><label class="f">Verlof tot<input class="i" type="date" name="lt"></label></div>${S.leave.length ? `<p class="muted">Verlof: ${esc(S.leave.map(l => l.from + ' t/m ' + l.to).join(', '))}</p>` : ''}</section>
  <section class="card stack"><h3>Boeken en betalen</h3><div class="grid2"><label class="f">Vasthouden tijdens betalen (min)<input class="i" type="number" name="hold" value="${S.holdMinutes}"></label><label class="f">Annuleren tot (uur vooraf)<input class="i" type="number" name="cancel" value="${S.cancelHours}"></label><label class="f">Wachtlijstaanbod geldig (min)<input class="i" type="number" name="wl" value="${S.waitlistOfferMinutes}"></label><label class="f">Reminder (uur vooraf)<input class="i" type="number" name="rem" value="${S.reminderHours}"></label></div>
    <label class="f">Leidende agenda in deze fase<select class="i" name="lead"><option value="app" ${S.leadingAgenda === 'app' ? 'selected' : ''}>Deze app</option><option value="salonized" ${S.leadingAgenda === 'salonized' ? 'selected' : ''}>Salonized (knop naar huidige boekingspagina)</option></select></label><p class="muted">Betaalprovider: testomgeving. Live configuratie nog niet ingericht.</p></section>
  <section class="card stack"><h3>VIP</h3><div class="grid2"><label class="f">VIP-voorsprong (uur)<input class="i" type="number" name="vipw" value="${S.vipWindowHours}"></label><label class="f">Intake-herinnering (dagen voor afspraak)<input class="i" type="number" name="vi" value="${S.vipReminders.intakeDaysBefore}"></label><label class="f">Haar bestellen: extra marge bovenop levertijd (dagen)<input class="i" type="number" name="vo" value="${S.vipReminders.orderHairExtraDays}"></label><label class="f">Definitief bevestigen (dagen vooraf)<input class="i" type="number" name="vc" value="${S.vipReminders.confirmDaysBefore}"></label></div><label class="chk"><input type="checkbox" name="vipp" ${S.vipPriority ? 'checked' : ''}><span>VIP-voorrang bij passende annuleringen</span></label></section>
  <section class="card stack"><h3>Salonadres</h3><div class="grid2"><label class="f">Straat en huisnummer<input class="i" name="street" value="${esc((S.address || {}).street || '')}"></label><label class="f">Postcode<input class="i" name="zip" value="${esc((S.address || {}).zip || '')}"></label><label class="f">Plaats<input class="i" name="city" value="${esc((S.address || {}).city || '')}"></label></div></section>
  <section class="card stack"><h3>Afhalen en verzenden</h3><label class="f">Afhaaltekst<input class="i" name="pickup" value="${esc(S.pickup)}"></label>${[...S.shipping, { country: '', rateCents: '' }].map((s, i) => `<div class="grid2"><label class="f">Land<input class="i" name="sc${i}" value="${esc(s.country)}"></label><label class="f">Tarief (€)<input class="i" name="sr${i}" inputmode="decimal" value="${s.rateCents === '' ? '' : eurIn(s.rateCents)}"></label></div>`).join('')}<input type="hidden" name="sn" value="${S.shipping.length + 1}"></section>
  <section class="card stack"><h3>Medewerkers</h3><p class="muted">Toegewezen werkfuncties. Financiële functies zijn altijd alleen voor jou.</p><div class="row">${['vandaag', 'agenda', 'inbox', 'klanten', 'voorraad'].map(p => `<label class="chk"><input type="checkbox" name="perm_${p}" ${S.employeePerms.includes(p) ? 'checked' : ''}>${p}</label>`).join('')}</div></section>
  <div class="row"><button class="btn">Instellingen opslaan</button><button type="button" class="btn ghost" data-act="resetDemo">Voorbeelddata opnieuw laden</button></div></form>`;
}
ACT.setSave = f => { const hours = {}; for (const d of [0, 1, 2, 3, 4, 5, 6]) hours[d] = f['open' + d] ? [[f['from' + d], f['to' + d]]] : [];
  const S = A.E.state.settings; const shipping = []; for (let i = 0; i < +f.sn; i++) if (f['sc' + i]) shipping.push({ country: f['sc' + i], rateCents: cents(f['sr' + i]) });
  const leave = [...S.leave]; if (f.lf && f.lt) leave.push({ from: f.lf, to: f.lt });
  if (call('own_settings_save', { address: { street: f.street, zip: f.zip, city: f.city }, hours, breaks: f.bf && f.bt ? [[f.bf, f.bt]] : [], longThroughBreakMin: +f.ltb || 0, leave, holdMinutes: +f.hold, cancelHours: +f.cancel, waitlistOfferMinutes: +f.wl, reminderHours: +f.rem, leadingAgenda: f.lead, vipWindowHours: +f.vipw, vipPriority: !!f.vipp, vipReminders: { ...S.vipReminders, intakeDaysBefore: +f.vi, orderHairExtraDays: +f.vo, confirmDaysBefore: +f.vc }, pickup: f.pickup, shipping, employeePerms: ['vandaag', 'agenda', 'inbox', 'klanten', 'voorraad'].filter(p => f['perm_' + p]) })) toast('Instellingen opgeslagen'); A.render(); };
ACT.resetDemo = () => A.confirmBox('Voorbeelddata opnieuw laden?', 'Alle gegevens in deze voorbeeldomgeving worden vervangen door de oorspronkelijke voorbeelddata.', 'doReset', {}, true);
ACT.doReset = () => { closeModal(); A.resetDemo(); };
function vAudit() { const L = must('own_audit'); return head('Logboek') + `<p class="muted">Wie wat wanneer deed, inclusief goedkeuringen en betaalwijzigingen.</p><div class="list">${L.map(l => `<div class="li"><span class="num"><small>${esc(dt(l.at))}</small></span><span><b>${esc(l.who)}</b> · ${esc(l.action)}<br><small>${esc(l.detail)}</small></span><span></span></div>`).join('') || '<div class="empty">Nog niets gelogd.</div>'}</div>`; }
}
